insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('ipswich-suffolk', 'Ipswich', 'Ipswich and Suffolk', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Suffolk''s family communities.', 'Ipswich, Bury St Edmunds, Stowmarket, Felixstowe, Woodbridge, Sudbury', 'Bury St Edmunds premium market town, London family influx, 350K+ territory, strong community culture, Woodbridge coastal premium.', 'NCT Suffolk, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4tt2b7024","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Suffolk has a charm that''s increasingly attracting young families from London and Essex looking for more space, better value, and a gentler pace of life. Ipswich is the county town with a population exceeding 140,000, while Bury St Edmunds adds a premium market town dimension. The territory covers over 350,000 residents across Suffolk''s main towns and their surrounding communities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7faiy7026","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4678g7027","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bury St Edmunds is the premium anchor, a beautiful Georgian market town with affluent families, independent shops, and a community culture that champions quality. Woodbridge and the wider Suffolk coast add further premium pockets. Ipswich provides urban volume and diversity. Parents across Suffolk value the county''s quality of life and invest in meaningful products for their families."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"msnf07029","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"94zlx7030","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Suffolk, and independent baby classes operate from venues throughout the territory. Community centres, church halls, and family hubs provide regular sessions, with Bury St Edmunds and Ipswich particularly well-served."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xk7oc7032","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n120m7033","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Suffolk offers a territory with genuine character. The premium market towns, growing Ipswich population, and the increasing influx of young families from London create a market that''s both established and expanding. The county''s quality of life and community spirit make it a rewarding place to be a Memory Catcher."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Ipswich and Suffolk region covers Ipswich, Bury St Edmunds, Stowmarket, Felixstowe, Woodbridge, and Sudbury. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6mgg930329","nodes":[{"id":"s53g730330","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jmaza14931","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Suffolk"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0rknx30332","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o1au214933","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sl4v930334","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lqx8p14935","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"bmx1p30336","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"z188s14937","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cets530338","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"owl9r14939","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Suffolk''s family communities are warm, genuine, and increasingly vibrant as new families discover the county. Bury St Edmunds'' engaged parent networks and the wider community infrastructure provide a strong foundation.', null, 'Baby Keepsake Franchise Opportunity in Ipswich and Suffolk', 'Start a flexible Memory Catcher franchise across Suffolk. Capture baby handprints and footprints locally with full training, support, and a protected region.', 52.06, 1.15, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('waltham-forest-redbridge', 'Waltham Forest and Redbridge', 'London: Waltham Forest and Redbridge', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North East London''s diverse, family-focused boroughs.', 'Walthamstow, Leytonstone, Chingford, Ilford, Woodford, South Woodford', 'Emerging family market, ''Awesomestow'' creative community, diverse multicultural demographics, strong baby class growth, accessible London territory.', 'NCT Waltham Forest and Redbridge, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s93ty1544","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Waltham Forest and Redbridge represent one of the most exciting emerging family markets in London. Walthamstow has undergone a remarkable transformation, earning the nickname ''Awesomestow'' as creative professionals and young families have moved in, drawn by more affordable housing, the village feel, and excellent transport links. Redbridge adds suburban depth through Woodford, South Woodford, and Ilford, where established family communities have deep roots."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pboi71546","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s1txn1547","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The diversity across these boroughs is a real strength. Families from dozens of cultural backgrounds share a common desire to celebrate and preserve their children''s earliest moments. From the trendy cafes and independent shops of Walthamstow Village to the traditional family streets of Woodford and Ilford, this territory offers breadth. Parents here are engaged and community-minded, with strong word-of-mouth networks that work in a Memory Catcher''s favour."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8va7d1549","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mzlag1550","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across both boroughs are well-attended and growing. NCT runs groups across the area, and a range of independent providers offer baby sensory, music, and development classes from community centres, church halls, and family hubs. Walthamstow''s baby class scene has expanded rapidly alongside its population growth, with new classes and venues opening regularly."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0eaoo1552","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s41mo1553","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory offers strong birth volumes at an accessible buy-in price. The combination of Walthamstow''s creative, affluent newcomers and Redbridge''s established family communities creates a balanced territory with consistent demand throughout the year."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Waltham Forest and Redbridge region covers Walthamstow, Leytonstone, Chingford, Ilford, Woodford, and South Woodford. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"af1yo25654","nodes":[{"id":"ymv3825655","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2gybl11212","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Waltham Forest and Redbridge"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fenks25657","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qr04311214","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"tdjdf25659","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"aen8j11216","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"k2dxu25661","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rgwqp11218","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"59qfq25663","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rhxw511220","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Walthamstow and Redbridge are diverse, welcoming, and growing. The mix of new creative families and established communities creates a warm environment where a Memory Catcher can build trusted relationships quickly.', null, 'Baby Keepsake Franchise Opportunity in Waltham Forest and Redbridge', 'Start a flexible Memory Catcher franchise across Waltham Forest and Redbridge. Capture baby handprints and footprints in North East London with full training, support, and a protected region.', 51.585, 0.02, 590000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('york-harrogate', 'York and Harrogate', 'York and Harrogate', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North Yorkshire''s most affluent family towns.', 'York, Harrogate, Knaresborough, Ripon, Wetherby, Tadcaster', 'Harrogate premium market, existing baby class partnership, historic York, affluent North Yorkshire market towns.', 'Established baby class partners, NCT York and Harrogate, independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1bve17889","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"York and Harrogate are two of the most desirable places to live in the North of England. Harrogate has some of the highest household incomes in Yorkshire, with an affluent parent community that invests in premium products. York combines historic charm with a thriving economy."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1ctjw7891","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w19t47892","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Harrogate parents expect quality and are willing to pay for it, making this one of the highest average order value territories in the North. York adds depth with its diverse family communities. Knaresborough, Ripon, and Wetherby contribute affluent suburban pockets."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"400sz7894","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gpt0o7895","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections. NCT runs active groups across both York and Harrogate. The baby class scene is vibrant and well-attended."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7jb817897","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"408px7898","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This is a premium territory with exceptional earning potential per session. Harrogate''s affluence, York''s growing family population, and existing baby class partnerships create a territory where quality and volume work together."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your York and Harrogate region covers York, Harrogate, Knaresborough, Ripon, Wetherby, and Tadcaster. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"xj8vt31330","nodes":[{"id":"e5aey31331","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c62ja15788","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ab5nu31333","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yk3l915790","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT York and Harrogate"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"vhe8q31335","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mw6wq15792","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"84hgq31337","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ln0ii15794","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"bpi0g31339","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"foeae15796","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across York and Harrogate are well-connected and quality-conscious. Existing baby class partnerships provides warm introductions.', null, 'Baby Keepsake Franchise Opportunity in York and Harrogate', 'Start a flexible Memory Catcher franchise across York and Harrogate with baby class partnerships. Capture baby handprints and footprints in North Yorkshire with full training and support.', 53.98, -1.3, 370000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('buckinghamshire', 'Buckinghamshire', 'Buckinghamshire: High Wycombe and Aylesbury', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Buckinghamshire''s affluent family communities.', 'High Wycombe, Aylesbury, Beaconsfield, Amersham, Chesham, Marlow', 'Ultra-affluent Beaconsfield and Amersham, Marlow riverside premium, Chilterns quality of life, flagship territory.', 'NCT Buckinghamshire, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"39t2s14568","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Buckinghamshire is one of the most affluent counties in England. Beaconsfield, Amersham, and Marlow are among the wealthiest towns in the country. The county''s proximity to London brings premium commuter family demographics."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"emgpi14570","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nsl6a14571","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"These are communities where parents invest significantly in their children. The Chilterns setting attracts families who value quality of life. Independent schools, village fetes, and community events create natural gathering points."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pliw814573","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wndlh14574","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across Buckinghamshire. Independent baby classes operate from venues throughout. The premium nature of the area supports quality providers."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s3npw14576","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"48g8t14577","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Buckinghamshire is a premium flagship territory. Among the highest average order value potential in the entire network."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Buckinghamshire region covers High Wycombe, Aylesbury, Beaconsfield, Amersham, Chesham, and Marlow. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"ecvrw56245","nodes":[{"id":"9h2jz56246","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sbsb456153","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Buckinghamshire"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"gvxci56248","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"00fym56158","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9c6xo56250","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rbprn56163","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium baby development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"th1ps56252","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1p1r656168","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"gccns56254","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s5j1z56173","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Buckinghamshire''s parenting communities are affluent, engaged, and well-connected.', null, 'Baby Keepsake Franchise Opportunity in Buckinghamshire', 'Start a flexible Memory Catcher franchise across Buckinghamshire. Capture baby handprints and footprints in one of England''s most affluent counties with full training and support.', 51.72, -0.78, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('kent-mid', 'Mid Kent', 'Mid Kent: Maidstone and Ashford', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Garden of England''s growing family communities.', 'Ashford, Maidstone South, Tenterden, Headcorn, Paddock Wood, Staplehurst', 'Ashford HS1 growth town, Tenterden premium Weald, Garden of England character, London commuter influx.', 'NCT Mid Kent, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9t12n14331","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Mid Kent covers Ashford, one of the fastest-growing towns in the South East, alongside the surrounding Garden of England communities. Ashford''s HS1 connection has accelerated family growth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j29pj14333","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"85j7z14334","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Tenterden is the premium pocket, a charming High Weald town with affluent, engaged families. Ashford provides volume through continuous new-build development. Staplehurst and Headcorn add village community charm."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"s