insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('kent-west', 'West Kent', 'West Kent: Tunbridge Wells and Sevenoaks', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across West Kent''s affluent family heartland.', 'Tunbridge Wells, Sevenoaks, Tonbridge, Maidstone, Cranbrook', 'Tunbridge Wells and Sevenoaks ultra-affluent, existing baby class partnership, 500K+ territory, flagship South East territory.', 'NCT West Kent, Established baby class partners, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v1h5q12003","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"West Kent is one of the most affluent areas in the South East. Tunbridge Wells and Sevenoaks regularly feature among the wealthiest towns in England. Maidstone adds county town volume. The territory exceeds 500,000 residents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1cyll12005","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0bbxz12006","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Tunbridge Wells'' Pantiles and independent shops attract quality-conscious families. Sevenoaks'' London commuter parents bring premium spending patterns. Tonbridge and surrounding villages add further affluent communities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphDat