corations":[],"text":"NCT West Kent"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"yvtk136320","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8mxh919907","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"wpscw36322","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wa7xx19909","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium baby development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5pm4i36324","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hq5l019911","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'West Kent''s parenting communities are well-connected and quality-driven. Existing baby class partnerships provides a warm start.', null, 'Baby Keepsake Franchise Opportunity in West Kent', 'Start a flexible Memory Catcher franchise across West Kent with baby class partnerships. Capture baby handprints and footprints in one of England''s most affluent areas with full training and support.', 51.19, 0.23, 500000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('stirling-falkirk', 'Stirling and Falkirk', 'Stirling and Falkirk', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Scotland''s Central Belt heartland.', 'Stirling, Falkirk, Grangemouth, Alloa, Dunblane', 'Central Belt location, Dunblane premium pocket, university city pipeline, 250K combined population, flexible full-time or part-time.', 'NCT Scotland, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ww0156546","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Stirling and Falkirk sit at the strategic heart of Scotland''s Central Belt, with a combined population of around 250,000. Stirling''s university city character and historic setting attract young professional families, while Falkirk''s growing population and family-friendly housing make it increasingly popular with families looking for Central Belt value. Dunblane adds a premium pocket with affluent families and a strong community identity."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7h07x6548","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f6lne6549","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities here are well-connected and growing. Stirling''s compact city centre and surrounding suburbs foster strong community bonds, while Falkirk''s expanding family areas bring new parents into the market regularly. Dunblane and Bridge of Allan are among the most desirable family areas in central Scotland, where quality-conscious parents invest in meaningful products."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ntny86551","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tug2u6552","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland runs groups in the area, and independent baby classes operate from venues across Stirling and Falkirk. Community centres, church halls, and family hubs provide regular sessions. The compact geography keeps travel manageable between the main population centres."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mehvz6554","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ruhyb6555","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Stirling and Falkirk offer a Central Belt location with good connectivity and a growing family market. This works well as either a full-time or part-time territory, with the premium Dunblane pocket providing above-average order values alongside the broader community volume."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Stirling and Falkirk region covers Stirling, Falkirk, Grangemouth, Alloa, and Dunblane. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"rvvjd29733","nodes":[{"id":"tr9zs29734","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sx66n14438","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland Central Belt"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cnqaa29736","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f1ot714440","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xoflp29738","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f2van14442","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"69euc29740","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"87a5z14444","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ho0qd29742","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5yldt14446","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Central Scotland''s family communities are warm and well-connected. Dunblane''s premium parent networks and the wider Stirling and Falkirk communities provide a balanced mix of quality and warmth.', null, 'Baby Keepsake Franchise Opportunity in Stirling and Falkirk', 'Start a flexible Memory Catcher franchise across Stirling and Falkirk. Capture baby handprints and footprints in Scotland''s Central Belt with full training, support, and a protected region.', 56.06, -3.86, 250000)
