insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bournemouth-poole', 'Bournemouth', 'Bournemouth, Christchurch and Poole', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Dorset''s premium coastal conurbation.', 'Bournemouth, Poole, Christchurch, Wimborne, Ferndown, Wareham', 'Sandbanks ultra-premium coast, 400K+ coastal conurbation, London family influx, beach lifestyle community.', 'NCT Bournemouth, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gkzra12486","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bournemouth, Christchurch and Poole form a coastal conurbation exceeding 400,000 residents. The area attracts young families from London drawn by beaches, good schools, and quality of life."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7wlup12488","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qttp012489","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Sandbanks and Canford Cliffs are among the most expensive addresses on the south coast. Poole Harbour''s communities are affluent and family-focused. The wider Bournemouth area provides volume and diversity."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qtsym12491","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vjjhi12492","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups. Independent baby classes thrive across the territory. The compact coastal geography keeps everything accessible."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vzf1n12494","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"agizc12495","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory offers coastal premium alongside consistent volume. The combination of one of England''s best beaches with strong community infrastructure makes it a desirable franchise."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bournemouth, Christchurch and Poole region covers Bournemouth, Poole, Christchurch, Wimborne, Ferndown, and Wareham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"mfvg636976","nodes":[{"id":"iqpzz36977","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s6tlq20387","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Bournemouth"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"648pg36979","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ahocz20389","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type"