insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('county-durham', 'County Durham', 'County Durham', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across County Durham''s proud communities.', 'Durham city, Bishop Auckland, Newton Aycliffe, Consett, Chester-le-Street, Peterlee', '530K+ population, Durham city university prestige, North East community loyalty, substantial volume.', 'NCT County Durham, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wt9cr14215","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"County Durham has a population exceeding 530,000. Durham city itself has cathedral and university prestige, while the wider county offers strong community-focused family markets."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ied2e14217","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3jqub14218","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Durham city attracts young university families. Chester-le-Street and the wider towns provide established community depth. These are proud communities where family comes first."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ftsrd14220","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bg6y314221","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across County Durham. Independent baby classes operate from community centres and family hubs throughout."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hsd0114223","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ujo8614224","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"County Durham offers substantial volume, Durham city''s premium anchor, and the kind of community loyalty that North East England is famous for."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your County Durham region covers Durham city, Bishop Auckland, Newton Aycliffe, Consett, Chester-le-Street, and Peterlee. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"i3k0d55572","nodes":[{"id":"ke4k255573","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4fh8755480","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT County Durham"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pjff155575","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1go9m55485","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sfuis55577","nodes":[{"paragraphData":{"textStyle":{"line