insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('cheshire-east', 'Macclesfield and Wilmslow', 'Cheshire East: Macclesfield and Wilmslow', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Cheshire''s affluent eastern corridor.', 'Macclesfield, Wilmslow, Alderley Edge, Knutsford, Poynton, Congleton', 'Cheshire golden triangle (Wilmslow, Alderley Edge, Knutsford), among the highest household incomes in the North, premium family demographics, exceptional average order value potential.', 'NCT Cheshire East, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"smdxc3771","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cheshire East''s golden triangle of Wilmslow, Alderley Edge, and Knutsford is home to some of the wealthiest families in the North of England. This is footballer and business-owner territory, where premium products and services are the norm and parents invest significantly in quality experiences for their children. Macclesfield adds a growing family population with a strong community identity, creating a territory that balances premium pricing with consistent volume."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"keghr3773","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oiviz3774","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family culture here is polished and aspirational. Parents in Wilmslow and Alderley Edge expect the best and are willing to pay for it, making average order values in this territory among the highest outside London. Knutsford''s charming character and excellent schools make it another premium pocket. Beyond the golden triangle, Macclesfield and Congleton provide grounded, family-rich communities with strong local values."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ngc8c3776","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"crxxs3777","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Cheshire East, and independent baby classes operate from venues throughout the territory. The premium areas in particular attract high-quality baby class providers, with well-attended sessions running throughout the week. Family centres and community venues across the wider area add further opportunities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"posx23779","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fhg2j3780","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cheshire East is a premium territory with exceptional earning potential. The concentration of wealthy families in the golden triangle, combined with the growing family communities across Macclesfield and Congleton, creates a territory where a Memory Catcher can build a genuinely high-value client base."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Cheshire East region covers Macclesfield, Wilmslow, Alderley Edge, Knutsford, Poynton, and Congleton. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"zt91w28686","nodes":[{"id":"sg4g528687","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p86jf13567","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Cheshire East"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"s4cke28689","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6ukxu13569","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"mx7vh28691","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"blceg13571","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium private baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"18tlp28693","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zckmj13573","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"r47q028695","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k0hzj13575","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Cheshire East''s golden triangle and wider area are well-connected and quality-driven. Recommendations travel quickly through established social networks, and parents here expect premium service from the businesses they trust.', null, 'Baby Keepsake Franchise Opportunity in Macclesfield and Wilmslow', 'Start a flexible Memory Catcher franchise across Cheshire East''s golden triangle. Capture baby handprints and footprints in one of the North''s most affluent family areas with full training and support.', 53.29, -2.18, 200000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('hull', 'Hull', 'Hull and East Riding', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Hull and the East Riding''s proud communities.', 'Hull city centre, Beverley, Cottingham, Hessle, Anlaby, Brough', 'Self-contained territory, Beverley premium market town, City of Culture legacy, 400K+ combined population.', 'NCT Hull, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"516w48252","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hull has a fierce civic pride amplified by its year as UK City of Culture. Together with the affluent East Riding communities of Beverley, Cottingham, and Hessle, the territory exceeds 400,000. Hull''s geographic isolation creates a self-contained market."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fxct98254","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b38px8255","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Beverley is the premium anchor, a beautiful market town with affluent families and independent shops. Hull provides volume with a young population and strong birth rates."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o9wbb8257","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"z7pk88258","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Hull and the East Riding. Independent baby classes operate from venues throughout. Beverley''s baby class scene is particularly vibrant."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yzndx8260","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ssr0c8261","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hull''s geographic isolation means a Memory Catcher here owns the market. Beverley''s premium pocket, Hull''s volume, and the self-contained nature create a compelling opportunity."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Hull and East Riding region covers Hull city centre, Beverley, Cottingham, Hessle, Anlaby, and Brough. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"qcw9331834","nodes":[{"id":"cd79531835","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gme5j16153","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Hull and East Riding"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sg8ge31837","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wrgvz16155","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9qt8t31839","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eik4s16157","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"6o7rt31841","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9ygyn16159","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"f7tg031843","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hl1es16161","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Hull''s community pride is legendary. Beverley''s premium parent networks and Hull''s vibrant family communities create a warm, loyal market.', null, 'Baby Keepsake Franchise Opportunity in Hull and East Riding', 'Start a flexible Memory Catcher franchise across Hull and the East Riding. Capture baby handprints and footprints locally with full training and support.', 53.76, -0.4, 400000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('merseyside-south', 'St Helens and Knowsley', 'Merseyside South: St Helens and Knowsley', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across south Merseyside''s family communities.', 'St Helens, Knowsley, Prescot, Huyton, Rainhill, Newton-le-Willows', '350K+ combined population, strong Merseyside community spirit, accessible pricing, excellent family infrastructure, loyal family communities.', 'NCT St Helens and Knowsley, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mxwva6060","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"St Helens and Knowsley have a combined population exceeding 350,000 and represent the family heartland of south Merseyside. These are proud, tight-knit communities with strong family values and a loyalty to local businesses that''s difficult to find elsewhere. The area attracts young families looking for affordable housing, good community infrastructure, and a genuine sense of belonging."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"avrc86062","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l2geb6063","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities here are defined by their warmth and authenticity. From the established suburbs of Rainhill and Newton-le-Willows, which attract professional families, to the vibrant communities across Huyton, Prescot, and St Helens town, parents here care deeply about their families and their local area. They support businesses they trust and they spread the word when they find something special."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"03g9d6065","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7dun46066","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the area, and independent baby classes operate from community centres, church halls, and family hubs throughout both boroughs. The strong community infrastructure means there are plenty of regular sessions for a Memory Catcher to attend, and the close-knit nature of these communities means word travels fast."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qgejr6068","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tnkys6069","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"South Merseyside offers excellent value as a franchise territory. The combined population provides strong volume, the community spirit is exceptional, and the accessible buy-in price makes this an attractive starting point. For a Memory Catcher who''s from the area or who can connect with these communities authentically, the earning potential is genuine."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Merseyside South region covers St Helens, Knowsley, Prescot, Huyton, Rainhill, and Newton-le-Willows. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"a77t029123","nodes":[{"id":"1zmpl29124","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pmc9k13936","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT St Helens and Knowsley"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"gfg9t29126","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5wzfn13938","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"76vo529128","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"362ja13940","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"h6c2329130","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"57e5l13942","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ofips29132","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"duydy13944","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'South Merseyside''s communities are fiercely loyal and deeply connected. The Merseyside warmth is real, and a Memory Catcher who earns the trust of these families will find the kind of community support that builds a sustainable business.', null, 'Baby Keepsake Franchise Opportunity in St Helens and Knowsley', 'Start a flexible Memory Catcher franchise across St Helens and Knowsley. Capture baby handprints and footprints locally with full training, support, and a protected region.', 53.45, -2.79, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('tower-hamlets-newham', 'Tower Hamlets and Newham', 'London: Tower Hamlets and Newham', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across East London''s fast-growing, family-rich boroughs.', 'Tower Hamlets, Newham, Bow, Stratford, Canary Wharf, Bethnal Green, Mile End', 'High birth rate London boroughs, Olympic regeneration area attracting young families, diverse multicultural communities, London premium pricing with high volume potential.', 'NCT Tower Hamlets and Newham, multiple baby class providers, family centres and community hubs', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fnxpy1071","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"East London has transformed over the past decade, and Tower Hamlets and Newham are at the heart of that change. The Olympic regeneration around Stratford and the continued development of Canary Wharf have attracted thousands of young professionals who are now starting families. Tower Hamlets alone has one of the highest birth rates of any London borough, with a diverse, multicultural population that values family deeply. Newham adds further volume with one of the youngest demographics in the capital."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qv7gm1073","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oxfl41074","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across these boroughs are vibrant and growing. From the converted warehouses of Bow and Bethnal Green, where creative professionals are raising families, to the new-build developments around Stratford and the established communities of East Ham and Forest Gate, this is a region where new parents are everywhere. The cultural diversity here is a real strength, families from all backgrounds share a desire to capture and preserve their children''s earliest moments."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k3oy51076","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2w8y51077","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Tower Hamlets and Newham are well established and growing. NCT runs groups across both boroughs, and a range of independent baby sensory, music, and development classes operate from community centres, family hubs, and private venues. The area''s strong network of children''s centres and family support organisations provide additional touchpoints for connecting with new parents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fnoqr1079","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"m41131080","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes this territory stand out is the combination of London premium pricing with high birth volumes. Unlike some of the ultra-premium West London territories where volume is lower, Tower Hamlets and Newham offer genuine scale. High birth rates, a young population, and the continued influx of new families through East London''s regeneration areas mean this territory''s potential is growing year on year."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Tower Hamlets and Newham region covers Tower Hamlets, Newham, Bow, Stratford, Canary Wharf, Bethnal Green, and Mile End. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6jug925065","nodes":[{"id":"vl3pb25066","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d30ve10741","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Tower Hamlets and Newham"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"tgqs325068","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7q5jx10743","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"evd6h25070","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e7utd10745","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sczj725072","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3h22j10747","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"wrwm225074","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"heku110749","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby rhyme time sessions and family groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'East London''s family communities are diverse and welcoming. The regeneration areas around Stratford and the established communities further east both offer warm, active parenting networks where a Memory Catcher can build trusted relationships quickly.', null, 'Baby Keepsake Franchise in Tower Hamlets and Newham', 'Start a flexible Memory Catcher franchise across Tower Hamlets and Newham in East London. Capture baby handprints and footprints locally with full training, support, and a protected region.', 51.53, -0.02, 660000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('down-lisburn', 'Lisburn and Down', 'Down and Lisburn', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across County Down and Lisburn''s family communities.', 'Lisburn, Downpatrick, Newcastle, Banbridge, Hillsborough, Dromore', 'Existing baby class partnerships, Hillsborough premium, fast-growing Lisburn, Mourne coast character.', 'Established baby class partners, NCT Northern Ireland, independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p6gfh15046","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"County Down and Lisburn have a combined population exceeding 350,000. Lisburn is one of Northern Ireland''s fastest-growing cities. Hillsborough adds Royal heritage charm and affluent families."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0qpjx15048","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w2fdb15049","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hillsborough is one of the most desirable addresses in Northern Ireland. Lisburn''s growth brings young families. The Mourne coast adds a unique character."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wrwqv15051","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5b15u15052","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections. NCT runs groups across the area. Independent baby classes operate throughout."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"uoylm15054","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9qbdc15055","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Down and Lisburn offer existing baby class partnerships, premium Hillsborough, and growing family communities. Note: different legal frameworks may apply for franchise agreements in Northern Ireland."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Down and Lisburn region covers Lisburn, Downpatrick, Newcastle, Banbridge, Hillsborough, and Dromore. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"aikr557158","nodes":[{"id":"x46ve57159","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fe9ke57076","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"2l22557161","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mht2l57081","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Northern Ireland"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kwfoe57163","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yrlh757086","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"6rl6157165","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"98hs257091","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"km5u757167","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g9r9c57096","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Down and Lisburn''s communities combine Northern Irish warmth with rural charm. Existing baby class partnerships provide a warm start.', null, 'Baby Keepsake Franchise Opportunity in Lisburn and County Down', 'Start a flexible Memory Catcher franchise across Down and Lisburn with baby class partnerships. Capture baby handprints and footprints locally with full training and support.', 54.42, -5.9, 230000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('huddersfield-calderdale', 'Huddersfield and Halifax', 'Huddersfield and Calderdale', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Pennine heartland''s family communities.', 'Huddersfield, Halifax, Dewsbury, Brighouse, Hebden Bridge, Holmfirth', '450K+ combined population, existing baby class partnerships, creative Pennine communities, diverse demographics.', 'Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"95yn38135","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Huddersfield and Calderdale have a combined population exceeding 450,000. Hebden Bridge has become one of the most creative, community-minded towns in the North."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pcp6s8137","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6d47j8138","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The diversity of this territory is its strength. Hebden Bridge''s artisan culture attracts premium-minded parents. Holmfirth adds Pennine charm. Huddersfield and Halifax provide urban volume with multicultural communities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"woq1a8140","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f1mb38141","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing an existing warm connection. NCT runs groups across the area. The territory''s geography means communities are naturally clustered."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ehcxp8143","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cta1a8144","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory offers character and variety that few others can match. The baby class partnership in Hebden Bridge provides a premium starting point."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Huddersfield and Calderdale region covers Huddersfield, Halifax, Dewsbury, Brighouse, Hebden Bridge, and Holmfirth. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"f71nj31612","nodes":[{"id":"s5usl31613","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n7quq16028","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rmv2w31615","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hny4y16030","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Huddersfield and Calderdale"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"x42yx31617","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"txjo316032","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ef3v931619","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4w3q316034","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5yyv031621","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wkebs16036","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The Pennine communities across this territory have a special warmth and character.', null, 'Baby Keepsake Franchise Opportunity in Huddersfield and Halifax', 'Start a flexible Memory Catcher franchise across Huddersfield and Calderdale with baby class partnerships. Capture baby handprints and footprints locally with full training and support.', 53.68, -1.82, 450000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('belfast', 'Belfast', 'Greater Belfast', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Northern Ireland''s capital and its surrounding communities.', 'Belfast city centre, South Belfast, East Belfast, Lisburn, Holywood, Bangor', 'NI capital (670K+ metro), existing baby class partnerships, premium South Belfast and north Down, premium South Belfast and north Down, renowned community warmth, flagship NI territory.', 'NCT Belfast, Established baby class partners, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7nzqp6667","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Belfast is Northern Ireland''s capital with a metropolitan population exceeding 670,000. The city has undergone a remarkable transformation over the past two decades, with thriving family communities established across South Belfast, East Belfast, and the surrounding towns. The young demographic profile and strong birth rates make Belfast the flagship Northern Ireland territory for the Memory Catcher network."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r0l426669","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cy7tj6670","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"South Belfast is the premium family area, with the leafy streets around the Malone Road, Stranmillis, and Ormeau attracting affluent professional families. Holywood and Bangor on the north Down coast add further premium pockets. The family communities across Belfast are warm, welcoming, and deeply connected through baby classes, church groups, and community networks. Northern Irish hospitality is renowned, and it extends right into the parenting world."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t1amu6672","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vsecb6673","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections. NCT runs groups across the city, and a wide range of independent baby sensory, music, and development classes operate from venues throughout the territory. The baby class scene in Belfast is vibrant and growing."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4fiix6675","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w61xo6676","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Belfast offers genuine scale, existing baby class partnerships, and the kind of community warmth that Northern Ireland is famous for. The 670,000+ metropolitan population provides a substantial market, and the premium areas of South Belfast and north Down drive strong average order values. Note: different legal frameworks may apply for franchise agreements in Northern Ireland."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Greater Belfast region covers Belfast city centre, South Belfast, East Belfast, Lisburn, Holywood, and Bangor. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"1lnjw29883","nodes":[{"id":"c1kxj29884","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5bozg14560","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0q24u29886","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1f0aa14562","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Belfast"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ni9zb29888","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vwgig14564","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"byllc29890","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gzk3t14566","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ipdui29892","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k7gn014568","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Belfast''s family communities are warm, welcoming, and deeply loyal. The existing baby class partnership provides a warm start, and Northern Irish hospitality creates the perfect environment for a Memory Catcher to build lasting relationships.', null, 'Baby Keepsake Franchise Opportunity in Belfast', 'Start a flexible Memory Catcher franchise across Greater Belfast with baby class partnerships. Capture baby handprints and footprints in Northern Ireland''s capital with full training and support.', 54.6, -5.93, 670000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('sunderland-south-tyneside', 'Sunderland', 'Sunderland and South Tyneside', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Wearside and South Tyneside''s proud family communities.', 'Sunderland, South Shields, Washington, Hebburn, Jarrow, Seaham', '420K+ combined population, fiercely proud communities, strong family values, accessible pricing.', 'NCT Sunderland and South Tyneside, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"12g8j7395","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Sunderland and South Tyneside have a combined population exceeding 420,000 and a community identity that''s fiercely proud and deeply family-oriented. The area''s strong working-class heritage has created communities where family comes first."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"68ag67397","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"69w3b7398","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities are warm and welcoming. Parents here value authenticity and genuine care above all else. A Memory Catcher who shows up consistently and cares about the families they serve will find loyal customers for life."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oaez87400","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gc4ox7401","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the area, and independent baby classes operate from community centres, church halls, and family hubs throughout Sunderland and South Tyneside."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w9uei7403","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"616bx7404","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Sunderland and South Tyneside offer strong volume at an accessible price point. The combined population is substantial, and the family-first values create the perfect environment for a Memory Catcher."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Sunderland and South Tyneside region covers Sunderland, South Shields, Washington, Hebburn, Jarrow, and Seaham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"bawnz30763","nodes":[{"id":"z9m0z30764","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b9gkt15296","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Sunderland and South Tyneside"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fphw630766","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jthy815298","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"vwltf30768","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"97zqm15300","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0ve5330770","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i4le015302","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ufomv30772","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bxaii15304","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Wearside and South Tyneside communities are built on genuine warmth and loyalty.', null, 'Baby Keepsake Franchise Opportunity in Sunderland and South Tyneside', 'Start a flexible Memory Catcher franchise across Sunderland and South Tyneside. Capture baby handprints and footprints locally with full training, support, and a protected region.', 54.94, -1.4, 420000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('richmond-kingston-wimbledon', 'Richmond, Kingston and Wimbledon', 'London: Richmond, Kingston and Wimbledon', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across South West London''s most affluent family boroughs.', 'Richmond, Kingston upon Thames, Wimbledon, Twickenham, Teddington, Hampton', 'Highest household income borough in London (£65K+ median), premium family demographics, village-like community feel, exceptional average order value potential.', 'NCT Richmond and Kingston, multiple premium baby class providers, private antenatal services', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g4reg2046","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Richmond upon Thames has the highest median household income of any borough in London at over £65,000 per year, and it shows. The families settling along the river in Twickenham, Teddington, and Richmond itself are professionals who value quality above all else. Kingston and Wimbledon add further depth, with established family communities, excellent schools, and the kind of leafy suburban feel that attracts parents looking to put down roots."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2ou1159472","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o53902048","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This part of South West London has a distinct character. It''s quieter than central London but no less affluent, with a village-like feel that makes community connections easier to build. Parents here are active in local groups, attend classes consistently, and form lasting friendships through the baby class circuit. That consistency is gold for a Memory Catcher, because you see the same families week after week, building trust and repeat business naturally."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sqyj259478","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5kxs82050","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is well established across Richmond and Kingston with regular antenatal courses and postnatal groups. Premium baby class providers run sessions throughout the week in church halls, community centres, and private venues. The baby class culture here skews premium, parents expect quality environments and are willing to pay for them, which aligns perfectly with the Memory Catcher offering."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fbcn72052","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c2nbs59484","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The spending power in this region is the highest of any territory in the UK. Lower overall birth volumes than some areas are more than compensated by the premium parents place on high-quality, handcrafted keepsakes. Every session here has the potential to generate above-average revenue, making this a quality-over-quantity territory with exceptional earning potential."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Richmond, Kingston and Wimbledon region covers Richmond upon Thames, Kingston upon Thames, Wimbledon, Twickenham, Teddington, and Hampton. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"mw87h24076","nodes":[{"id":"hrq3624077","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rjh3h9875","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Richmond and Kingston"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"tfyz324079","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t173o9877","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium private antenatal classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ijl1g24081","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"23g7n9879","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"1g0pb24083","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"01cgs9881","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls across SW London"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rwahr24085","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n8i269883","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and library groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting community across Richmond and Kingston is well organised and deeply connected. NCT groups here form some of the strongest social bonds in London, and being introduced as a trusted partner through those networks gives you an immediate advantage.', null, 'Baby Keepsake Franchise, Richmond & Kingston London', 'Start a flexible Memory Catcher franchise across Richmond, Kingston, and Wimbledon. Capture baby handprints and footprints in London''s most affluent family boroughs with full training and support.', 51.43, -0.28, 420000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('salisbury-dorset', 'Salisbury', 'Salisbury and North Dorset', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Salisbury Plain and North Dorset''s communities.', 'Salisbury, Blandford Forum, Shaftesbury, Amesbury, Warminster, Gillingham', 'Cathedral city charm, military family pipeline, 250K+ territory, North Dorset market towns, flexible full-time or part-time.', 'NCT Salisbury, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c8pu914094","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Salisbury and its surrounding area have a combined population around 250,000. The military presence at Bulford and Larkhill provides young families. Salisbury itself has cathedral city charm."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wxazi14096","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4cbxa14097","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Military families often lack extended family support and deeply value keepsake services. Salisbury''s heritage character attracts quality-conscious families. The North Dorset market towns add rural warmth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y7wem14099","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eg60t14100","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups in Salisbury. Independent baby classes operate from community centres and military family facilities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ertjs14102","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r70ln14103","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Salisbury combines heritage city appeal with a significant military family population. The territory works well as either full-time or part-time."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Salisbury and North Dorset region covers Salisbury, Blandford Forum, Shaftesbury, Amesbury, Warminster, and Gillingham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"2zpoh38687","nodes":[{"id":"8gftn38688","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rr3uy21956","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Salisbury"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"vrlvj38690","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f87hn21958","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Military family groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"k8a8238692","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x5nla21960","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5f98b38694","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"npjsq21962","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"zu6o838696","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ntk3621964","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Salisbury''s communities combine military family warmth with cathedral city character.', null, 'Baby Keepsake Franchise Opportunity in Salisbury', 'Start a flexible Memory Catcher franchise across Salisbury and North Dorset. Capture baby handprints and footprints locally with full training and support.', 51.02, -1.94, 250000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('southampton', 'Southampton', 'Hampshire North: Southampton and Eastleigh', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Southampton and its growing family suburbs.', 'Southampton, Eastleigh, Romsey, Chandlers Ford, Hedge End, Totton', 'South coast''s largest city, 400K+ territory, Chandlers Ford and Romsey premium, university pipeline.', 'NCT Southampton, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tmhjj10308","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Southampton is the largest city on the south coast with a population exceeding 260,000. The surrounding towns bring the territory well above 400,000. Two universities provide a pipeline of young families."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t2z8710310","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dbvgv10311","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Chandlers Ford and Romsey are the premium family areas. Eastleigh and Hedge End are growing suburbs with younger demographics. Parents across the territory value quality experiences."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gq7ov10313","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cwom910314","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across the wider area. Independent baby classes operate throughout. The baby class scene is well-established."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"54ao610316","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ak83i10317","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Southampton offers major south coast city scale with premium suburbs that drive strong average order values."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Hampshire North region covers Southampton, Eastleigh, Romsey, Chandlers Ford, Hedge End, and Totton. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"wtj2u34409","nodes":[{"id":"ae98y34410","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p0vx018135","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Southampton"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"vmymk34412","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d9tlt18137","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qp9yt34414","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"chvqz18139","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"x7iip34416","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4qf1k18141","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jqrzx34418","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y6nxw18143","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Southampton''s parenting communities are diverse and growing.', null, 'Baby Keepsake Franchise Opportunity in Southampton', 'Start a flexible Memory Catcher franchise across Southampton. Capture baby handprints and footprints locally with full training and support.', 50.93, -1.4, 400000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('kingston-epsom', 'Kingston and Epsom', 'London: Kingston and Epsom', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across South West London''s affluent commuter belt.', 'Kingston upon Thames, Epsom, Surbiton, New Malden, Esher, Claygate', 'Affluent South West London commuter belt, premium family demographics, strong NCT networks, ultra-premium pockets in Esher and Claygate.', 'NCT Kingston, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ga6642772","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Kingston upon Thames and the surrounding Epsom area represent one of the most affluent family markets in the wider London region. These are the suburbs where professional families settle for the long term, drawn by outstanding schools, riverside living, and a quality of life that combines the best of London access with genuine suburban charm. The demographic here skews towards engaged, affluent parents who invest in quality products and meaningful experiences for their children."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yj6eb2774","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cpyqy2775","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The community feel across Kingston, Surbiton, and Epsom is strong. Parents here form tight social networks through baby classes and school communities, and recommendations travel fast. New Malden adds a vibrant Korean community that has become one of the area''s defining features, bringing additional cultural richness and family values to the territory. Esher and Claygate provide ultra-premium pockets where average order values run high."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jnaxq2777","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7tk2h2778","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is well-established across the area with regular antenatal and postnatal groups. Independent baby classes, including sensory, music, and yoga sessions, run from venues throughout the territory. The baby class scene in Kingston and Surbiton is particularly active, with a full weekly calendar that a Memory Catcher can tap into from day one."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5e3ga2780","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"acl9h2781","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory is defined by quality. The affluent demographics, strong community bonds, and premium pricing potential make it an excellent opportunity for a Memory Catcher who values building deep, lasting relationships with families. Every session here has the potential to generate above-average revenue."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Kingston and Epsom region covers Kingston upon Thames, Epsom, Surbiton, New Malden, Esher, and Claygate. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"4zgft27158","nodes":[{"id":"ux1u627159","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yxygf12468","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Kingston"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0cj0j27161","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9q4dv12470","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"l10qd27163","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l216y12472","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"tymy127165","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zk2pi12474","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"bo7sy27167","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"42c3h12476","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Kingston, Surbiton, and Epsom are well-connected and recommendation-driven. Strong NCT networks and active baby class communities mean a Memory Catcher can build a trusted reputation quickly.', null, 'Baby Keepsake Franchise Opportunity in Kingston and Epsom', 'Start a flexible Memory Catcher franchise across Kingston and Epsom. Capture baby handprints and footprints in South West London''s affluent family suburbs with full training and support.', 51.355, -0.275, 250000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('blackburn-burnley', 'Blackburn and Burnley', 'Blackburn and Burnley', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across East Lancashire''s family-rich communities.', 'Blackburn, Burnley, Accrington, Darwen, Clitheroe, Padiham', '350K+ combined population, existing baby class partnership, young diverse demographics, Ribble Valley premium pocket, strong community loyalty.', 'Established baby class partners, NCT groups, multiple independent baby class providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b246p5653","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"East Lancashire has a combined population exceeding 350,000 across Blackburn, Burnley, Accrington, and the surrounding towns. Blackburn in particular has one of the youngest populations in the North West, with a diverse, multicultural community where family is central to everything. Birth rates across this area are strong, providing a consistent stream of new parents for a Memory Catcher to connect with."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u2mq063909","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ird6o5655","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The communities across East Lancashire are tight-knit and loyal. From the Ribble Valley market towns like Clitheroe, where affluent families enjoy a semi-rural lifestyle, to the vibrant multicultural communities of Blackburn and Burnley, these are places where genuine trust and personal connections matter more than anything. Parents here support businesses they believe in, and once you''ve earned that trust, the community has your back."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l7b2f63915","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ujow65657","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections. NCT groups run across the area, and independent baby sensory, music, and development classes operate from community centres, church halls, and family hubs. The community infrastructure here is strong and deeply embedded in local life."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v9fye63921","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ckfy95659","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"East Lancashire offers volume, warmth, and existing baby class partnerships at an accessible price point. The Ribble Valley adds a premium pocket for higher average order values, while the broader territory provides the consistent demand that supports a full-time franchise."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Blackburn and Burnley region covers Blackburn, Burnley, Accrington, Darwen, Clitheroe, and Padiham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"nd13y28525","nodes":[{"id":"5oxri28526","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yna1h13446","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"j3b8528528","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vojsa13448","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across East Lancashire"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"6qoi128530","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d995913450","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qjo8v28532","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sr2sr13452","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5i6no28534","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qf9gs13454","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'East Lancashire''s communities are among the most loyal and tight-knit you''ll find anywhere. The strong family values across the area, combined with the fierce local pride of these towns, create the perfect environment for a Memory Catcher who becomes part of the community.', null, 'Baby Keepsake Franchise Opportunity in Blackburn and Burnley', 'Start a flexible Memory Catcher franchise across Blackburn and Burnley with baby class partnerships in place. Capture baby handprints and footprints locally with full training and support.', 53.77, -2.36, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('ealing-hounslow', 'Ealing and Hounslow', 'London: Ealing and Hounslow', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across West London''s thriving family boroughs.', 'Ealing, Hounslow, Chiswick, Acton, Hanwell, Brentford, Isleworth', '''Queen of the Suburbs'' Ealing, premium Chiswick pocket, diverse Hounslow demographics, strong baby class infrastructure, established family communities.', 'NCT Ealing and Hounslow, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h1pkx2177","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Ealing has long been known as the ''Queen of the Suburbs'' and for good reason. This West London borough combines beautiful green spaces, excellent schools, and a strong sense of community that makes it one of the most popular places in the capital for families. Chiswick adds a premium dimension with its riverside setting and affluent family demographic. Hounslow brings diversity and volume with a young, growing population."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ujy9z2179","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"a5hfa2180","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family culture across these boroughs is vibrant and well-established. Ealing and Chiswick are packed with young families who invest in their children''s experiences, attend classes regularly, and form strong social networks through the baby class circuit. The independent high streets, weekend farmers'' markets, and community events create natural gathering points where parents connect and share recommendations."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hhyvm2182","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4ihjt2183","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across both boroughs, and a wide range of independent baby classes operate from venues throughout the territory. Chiswick''s baby class scene is particularly busy, with multiple providers running sessions from church halls, community centres, and private studios. Ealing Broadway and the surrounding areas add further depth with growing numbers of baby and toddler groups."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w8roe2185","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b9i5q2186","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory offers the best of West London, premium family areas in Chiswick and Ealing with the added volume of Hounslow''s diverse communities. The transport links keep the territory connected, and the established community infrastructure means a Memory Catcher can fill their diary quickly."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Ealing and Hounslow region covers Ealing, Hounslow, Chiswick, Acton, Hanwell, Brentford, and Isleworth. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"g9h9526465","nodes":[{"id":"0voet26466","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y22a711825","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Ealing and Hounslow"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"2qoiq26468","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"28rk211827","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"szwm326470","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4dj5v11829","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"74d1126472","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0ch7s11831","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sr4c126474","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dtsmv11833","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'West London''s family communities are warm, engaged, and fiercely loyal to local businesses. The ''Queen of the Suburbs'' reputation is well-earned, and the parenting networks here are among the most active in outer London.', null, 'Baby Keepsake Franchise Opportunity in Ealing and Hounslow', 'Start a flexible Memory Catcher franchise across Ealing and Hounslow. Capture baby handprints and footprints in West London with full training, support, and a protected region.', 51.5, -0.35, 660000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('brent-harrow', 'Brent and Harrow', 'London: Brent and Harrow', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North West London''s diverse family communities.', 'Wembley, Harrow, Kilburn, Willesden, Kingsbury, Kenton, Wealdstone', 'One of London''s most diverse boroughs (149+ languages), strong birth rates, Wembley regeneration attracting young families, well-established Harrow suburbs.', 'NCT Brent and Harrow, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i8xxt2655","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Brent is one of the most diverse boroughs in London, with over 149 languages spoken and a young population that generates strong birth rates year after year. The regeneration around Wembley has brought thousands of new families into the area, while established communities in Kilburn, Willesden, and Kingsbury provide deep roots and strong local networks. Combined with Harrow''s well-established family suburbs, this territory covers a substantial and growing market."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"laot22657","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"98edf2658","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The diversity across these boroughs is a genuine asset for a Memory Catcher. Families from dozens of cultural backgrounds share a universal desire to preserve their children''s earliest moments, and the multicultural character of the area creates a rich, warm community. Parents here are engaged, community-minded, and loyal to businesses that earn their trust through genuine relationships."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ny1ej2660","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sam132661","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Brent and the wider area are well-attended and growing. NCT runs groups across the territory, and a range of independent providers offer baby sensory, music, and development classes from community centres, church halls, and family hubs. The Wembley area has seen a particular increase in baby classes as the regeneration has brought more young families into the neighbourhood."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"edn1p2663","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vrs2y2664","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory combines diversity, volume, and community warmth. The birth rates are strong, the family infrastructure is well-developed, and the cultural richness of the area means every session brings something different. For a Memory Catcher who thrives on variety and connection, this is a rewarding territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Brent and Harrow region covers Wembley, Harrow, Kilburn, Willesden, Kingsbury, Kenton, and Wealdstone. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"nukbl27021","nodes":[{"id":"c1o5h27022","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4lxed12349","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Brent and Harrow"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fikbt27024","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k73a212351","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"lyu2r27026","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"89m2812353","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kxs7627028","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bfvya12355","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"klc1z27030","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iewcs12357","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Brent and Harrow are diverse, welcoming, and deeply connected. The multicultural character of these boroughs creates warm, inclusive baby class communities where a Memory Catcher can build trusted relationships across all backgrounds.', null, 'Baby Keepsake Franchise Opportunity in Brent and Harrow', 'Start a flexible Memory Catcher franchise across Brent and Harrow in North West London. Capture baby handprints and footprints locally with full training, support, and a protected region.', 51.575, -0.305, 600000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('hackney-islington', 'Hackney and Islington', 'London: Hackney and Islington', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across two of North East London''s most vibrant, family-rich boroughs.', 'Hackney, Islington, Stoke Newington, Dalston, Highbury, Finsbury Park, Angel', 'Vibrant inner London boroughs, high birth rates, strong independent culture, ''Nappy Newington'' family hub, London premium pricing.', 'NCT Hackney and Islington, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"et3ji1193","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hackney and Islington have undergone one of the most dramatic transformations of any London boroughs over the past two decades. What were once gritty inner-city areas are now among the most desirable places in the capital for young families. The median age in Hackney sits at just 33, and the borough''s birth rate remains one of the highest in inner London. Islington adds a professional, affluent dimension with its Georgian terraces around Highbury and Angel attracting families who want city living without sacrificing space."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vmjim1195","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u5z4y1196","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The parenting culture across these boroughs is engaged, community-driven, and independent-minded. From the coffee shops and delis of Stoke Newington, often called ''Nappy Newington'' by locals, to the creative parent communities of Dalston and the professional families of Highbury Fields, these are parents who actively seek out meaningful, handcrafted products for their children. The Memory Catcher service fits this audience perfectly."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i1oxe1198","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8ojii1199","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Hackney and Islington are thriving. NCT runs well-attended groups across both boroughs, and a wide range of independent baby sensory, music, yoga, and development classes operate from community centres, church halls, and private studios. The density of venues in this compact urban area means a franchisee can attend multiple sessions per day without long travel times between them."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kkql21201","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t6reu1202","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes this territory particularly compelling is the combination of high birth volumes, engaged parents, and London premium pricing. Hackney''s diversity and Islington''s affluence create a broad customer base, and the tight geography keeps travel efficient. This is a territory where a Memory Catcher can build a full diary quickly."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Hackney and Islington region covers Hackney, Islington, Stoke Newington, Dalston, Highbury, Finsbury Park, and Angel. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"i032q25234","nodes":[{"id":"al3wa25235","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0wbny10856","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Hackney and Islington"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fqpm125237","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cj8xv10858","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"g1ikt25239","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k9mb710860","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xvh9z25241","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eg9n710862","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ep37q25243","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5tknk10864","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Hackney and Islington''s parenting communities are tight-knit and recommendation-driven. The independent culture here means parents actively champion local businesses they believe in, and word of mouth travels fast through the baby class networks.', null, 'Baby Keepsake Franchise Opportunity in Hackney and Islington', 'Start a flexible Memory Catcher franchise across Hackney and Islington. Capture baby handprints and footprints in North East London with full training, support, and a protected region.', 51.55, -0.08, 520000)
