om":"0px","paddingTop":"0px"},"id":"zw6sv10069","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8tc8010070","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs well-attended groups. Independent baby classes operate from venues throughout. The university culture encourages a rich offering of parent groups."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hg65f10072","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8e1u810073","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Oxford''s combination of academic prestige, international families, and affluent surrounding towns creates a territory with exceptional average order value potential."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Oxford and South Oxfordshire region covers Oxford, Abingdon, Didcot, Henley-on-Thames, Thame, and Wallingford. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"2d2ig34066","nodes":[{"id":"koden34067","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i6ax417893","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Oxford"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"m9m3734069","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"00r4517895","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"c224b34071","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qgccx17897","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"University parent groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pva2g34073","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wvp4s17899","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7rd7a34075","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2q5vx17901","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Oxford''s parenting community is engaged, international, and quality-driven.', null, 'Baby Keepsake Franchise Opportunity in Oxford', 'Start a flexible Memory Catcher franchise across Oxford and South Oxfordshire. Capture baby handprints and footprints in one of England''s most prestigious areas with full training and support.', 51.7, -1.2, 310000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('derby', 'Derby', 'Derby and South Derbyshire', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Derby and its growing family suburbs.', 'Derby city centre, Allestree, Mickleover, Littleover, Burton upon Trent, Swadlincote', '460K+ combined territory, premium Allestree and Mickleover, Burton upon Trent volume, A38/A50 connectivity.', 'NCT Derby, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n2et28785","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Derby has a population exceeding 260,000, with Burton upon Trent and South Derbyshire adding 200,000+ to create a substantial territory. The surrounding suburbs of Allestree, Mickleover, and Littleover are popular family areas."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tmggl8787","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"153g38788","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Allestree and Mickleover attract affluent professional families. Burton upon Trent and Swadlincote bring additional volume. Parents here are community-minded and loyal to local businesses."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"sty