],"type":"LIST_ITEM"},{"id":"rzbxi32424","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p801l16640","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4a5pa32426","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fi7dy16642","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"arqeu32428","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x9m2h16644","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Derby''s family communities are genuine and loyal.', null, 'Baby Keepsake Franchise Opportunity in Derby', 'Start a flexible Memory Catcher franchise in Derby and South Derbyshire. Capture baby handprints and footprints locally with full training and support.', 52.87, -1.5, 460000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('lincoln', 'Lincoln', 'Lincoln and North Lincolnshire', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Lincolnshire''s cathedral city.', 'Lincoln, Scunthorpe, Gainsborough, Market Rasen, Sleaford', 'Cathedral city prestige, university pipeline, 350K+ territory, strong community roots, accessible pricing.', 'NCT Lincoln, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9h2kq13138","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lincoln and North Lincolnshire have a combined population exceeding 350,000. Lincoln''s cathedral city status brings prestige and a university pipeline of young families."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1w2as13140","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pk4c213141","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lincoln''s Bailgate and Uphill areas attract affluent families. The wider territory provides volume. Lincolnshire''s strong agricultural heritage creates communities with deep family roots."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bxwmt13143","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9e6bh13144","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the area. Independent baby classes operate from community centres and family hubs throughout."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"m1req13146","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"32xpm13147","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lincoln''s self-contained geography and growing university community create a clear market with manageable territory size."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Lincoln and North Lincolnshire region covers Lincoln, Scunthorpe, Gainsborough, Market Rasen, and Sleaford. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"ohr6g37551","nodes":[{"id":"vvu3l37552","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cdcsz20880","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Lincoln"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5d8ah37554","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b6r8r20882","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fit7b37556","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rnn2d20884","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ycfby37558","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xgc6w20886","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rm3uq37560","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9nhjg20888","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Lincoln''s communities are rooted and genuine.', null, 'Baby Keepsake Franchise Opportunity in Lincoln', 'Start a flexible Memory Catcher franchise across Lincoln. Capture baby handprints and footprints locally with full training and support.', 53.4, -0.58, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('norwich', 'Norwich', 'Norwich and Norfolk', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Norfolk''s vibrant cathedral city.', 'Norwich city centre, Golden Triangle, Thorpe St Andrew, Wymondham, Aylsham', 'UNESCO City of Literature, Golden Triangle premium area, self-contained market, creative independent culture, strong community identity.', 'NCT Norwich, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"llhxu6905","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Norwich is one of the most self-contained cities in England, sitting in relative isolation from other major centres. That isolation is its advantage. The city has a population exceeding 210,000, with the wider territory adding further depth. Norwich''s Golden Triangle is the premium family area, where Victorian terraces, independent shops, and a strong community feel attract engaged, quality-conscious parents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0z1786907","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nirb96908","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family culture in Norwich is creative, independent, and deeply community-minded. The city has been recognised as a UNESCO City of Literature, and that creative spirit extends into its parenting culture. Parents here actively seek out meaningful, handcrafted products and champion local businesses. The Golden Triangle and surrounding areas have particularly vibrant baby class and community group scenes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5qost6910","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lisse6911","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across Norwich, and independent baby classes operate from venues throughout the city and surrounding areas. The compact city geography keeps everything accessible, and the strong community infrastructure provides a full calendar of sessions."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zuc8b6913","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k8ijw6914","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Norwich''s self-contained market means a Memory Catcher here owns the territory in a way that''s harder to achieve in more connected regions. The creative culture, engaged parents, and premium Golden Triangle pocket create a territory with character and quality."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Norwich and Norfolk region covers Norwich city centre, the Golden Triangle, Thorpe St Andrew, Wymondham, and Aylsham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"2cl8230162","nodes":[{"id":"f04f230163","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5hxkd14815","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Norwich"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qsib630165","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jrmpo14817","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"x4y1t30167","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vqkhh14819","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kkk4u30169","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cn6f914821","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"w7s8z30171","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8p2x814823","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Norwich''s parenting community is creative, engaged, and fiercely independent. The city''s self-contained character creates strong community bonds and natural loyalty to local businesses.', null, 'Baby Keepsake Franchise Opportunity in Norwich', 'Start a flexible Memory Catcher franchise across Norwich and Norfolk. Capture baby handprints and footprints locally with full training, support, and a protected region.', 52.63, 1.3, 400000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('devon-north', 'North Devon and Torbay', 'North Devon and Torbay', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North Devon''s surf coast and Torbay''s English Riviera.', 'Barnstaple, Bideford, Torquay, Paignton, Newton Abbot, Teignmouth', 'English Riviera and surf coast, 350K+ combined, coastal lifestyle families, two distinctive areas.', 'NCT Devon, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x6vb415417","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Devon and Torbay cover two distinct but complementary areas of Devon with a combined population exceeding 350,000. Torbay''s English Riviera and North Devon''s surf coast attract families drawn to coastal living."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ct60p15419","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1d0sn15420","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Torbay''s family communities are growing as young professionals discover affordable coastal living. North Devon''s independent spirit creates communities that champion local businesses."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iouol15422","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7wd0p15423","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Devon. Independent baby classes operate from community centres and family hubs. The territory''s two distinct areas allow flexible scheduling."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dvqbl15425","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4gh7115426","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory covers two of Devon''s most distinctive coastal areas, offering variety and character."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your North Devon and Torbay region covers Barnstaple, Bideford, Torquay, Paignton, Newton Abbot, and Teignmouth. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"oup4j57899","nodes":[{"id":"3t24d57900","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r67qt57817","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Devon"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"n57y457902","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2kzw857822","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5slvu57904","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pewe957827","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"oe0pa57906","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u8cuo57832","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"1iogi57908","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k4tpj57837","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Devon''s coastal communities are independent, warm, and deeply connected.', null, 'Baby Keepsake Franchise Opportunity in North Devon and Torbay', 'Start a flexible Memory Catcher franchise across North Devon and Torbay. Capture baby handprints and footprints on Devon''s coast with full training and support.', 50.9, -3.85, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bristol', 'Bristol', 'Bristol', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the South West''s creative capital, where artisan culture meets family life.', 'Bristol city centre, Clifton, Redland, Bishopston, Cotham, Southville, Bedminster', 'South West''s largest city (494K), median age 33.4, strong artisan and independent culture, premium family areas in Clifton and Redland, 11.4% population growth over past decade.', 'NCT Bristol, multiple independent baby class providers, strong community group culture', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x0975849","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bristol is the largest city in the South West with a population of 494,400, and it has one of the youngest age profiles of any major UK city. The median age is just 33.4 years, nearly seven years below the national average. Over the past decade, Bristol''s population has grown by over 50,000 people, an 11.4% increase, making it one of the fastest-growing Core Cities in England. That growth is driven in large part by young professionals settling into family life across the city''s desirable neighbourhoods."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x7v0s60521","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9pnud851","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes Bristol special for a Memory Catcher is its culture. This is a city that champions independent, artisan, and handcrafted businesses. From Gloucester Road''s independent shops to Southville''s creative community, Bristol parents actively seek out products that are made with care and have a story behind them. The Memory Catcher service, beautiful, handcrafted keepsakes of their baby''s tiny prints, couldn''t be a better fit for this audience."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5tx8160527","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6yfmm853","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is very active across Bristol with well-attended antenatal courses and postnatal groups. The city''s community group culture is exceptionally strong, with baby classes, parent meetups, and family groups running from venues across Clifton, Redland, Bishopston, Cotham, Southville, and Bedminster. Bristol has more than 287 ethnic groups and over 90 languages spoken, creating a rich, diverse family community that values connection and belonging."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oh2wo60533","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h4stf855","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Clifton and Redland are the premium pockets of the territory, where affluent professional families drive above-average order values. But Bristol''s strength is its breadth, every neighbourhood has active parenting communities, and the city''s compact geography means you can attend multiple sessions across different areas in a single day. As the South West''s anchor territory, this is a region with genuine room to grow."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bristol region covers Bristol city centre, Clifton, Redland, Bishopston, Cotham, Southville, and Bedminster. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"4si3y24928","nodes":[{"id":"1f4lx24929","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ok87110597","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Bristol antenatal and postnatal groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"85iya24931","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lb97x10599","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"wfsf024933","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h3qlg10601","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Parent and baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"189ba24935","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4ll9u10603","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls across Bristol"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0os6f24937","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2p30s10605","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs, library groups, and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Bristol''s parenting community is active, engaged, and fiercely loyal to businesses they believe in. The city''s independent culture means that a personal, handcrafted service like Memory Catchers will resonate deeply. Once you''re known in the community, Bristol parents become your biggest advocates.', null, 'Baby Keepsake Franchise in Bristol, South West | Apply', 'Start a flexible Memory Catcher franchise in Bristol. Capture baby handprints and footprints across the South West''s creative capital with full training, support, and a protected region.', 51.455, -2.585, 495000)
