"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6vpto17134","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"y5mcp33119","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"56mg717136","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ae03033121","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ouqym17138","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The Potteries communities are warm, genuine, and loyal.', null, 'Baby Keepsake Franchise Opportunity in Stoke-on-Trent', 'Start a flexible Memory Catcher franchise across Stoke-on-Trent and North Staffordshire. Capture baby handprints and footprints locally with full training and support.', 53, -2.18, 500000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('plymouth', 'Plymouth', 'Plymouth and South Devon', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Plymouth and the South Devon coast.', 'Plymouth city centre, Plymstock, Ivybridge, Totnes, Kingsbridge, Tavistock', 'Largest Devon city, naval family pipeline, Totnes artisan premium, 260K+ population, self-contained market.', 'NCT Plymouth, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qmmuy12373","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Plymouth is the largest city in Devon with a population exceeding 260,000. The naval base provides a constant pipeline of young families. Totnes adds an artisan premium pocket."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2n7oj12375","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"subpb12376","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Naval families particularly value keepsakes when partners are deployed. Totnes is one of the most creative towns in England, where handcrafted products are celebrated. Plymstock and Ivybridge add established family suburbs."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rgqmz12378","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dpbl812379","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Plymouth. Independent baby classes operate throughout. The military family community has its own support networks."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wy51512381","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t7v9112382","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Plymouth combines city scale, naval family demand, and the unique premium dimension of Totnes. The self-contained geography creates a clear market."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Plymouth and South Devon region covers Plymouth city centre, Plymstock, Ivybridge, Totnes, Kingsbridge, and Tavistock. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"h90gt36839","nodes":[{"id":"26yav36840","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dtml120269","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Plymouth"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"byiki36842","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ufp3f20271","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Military family support groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"2e79x36844","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6wxzr20273","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ti4ce36846","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t2ntx20275","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"r98ag36848","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o22kc20277","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Plymouth''s family communities are resilient, warm, and deeply connected. The naval family network adds a unique dimension.', null, 'Baby Keepsake Franchise Opportunity in Plymouth', 'Start a flexible Memory Catcher franchise across Plymouth and South Devon. Capture baby handprints and footprints locally with full training and support.', 50.42, -3.9, 260000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('lancashire-central', 'Preston and Chorley', 'Lancashire Central: Preston and Chorley', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Lancashire''s growing central belt.', 'Preston, Chorley, Leyland, Buckshaw Village, Fulwood, Penwortham', '380+ birth increase in 2024 (bucking national trend), rapidly growing Buckshaw Village, Preston premium suburbs, strong and expanding family infrastructure.', 'NCT Preston and Chorley, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s4emr5784","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Central Lancashire is one of the fastest-growing areas in the North West. Preston has city status and a population exceeding 145,000, while Chorley, Leyland, and the rapidly expanding Buckshaw Village add a further 200,000+ residents. Lancashire recorded one of the largest increases in live births in 2024, with 380 more babies than the previous year, making this one of the regions bucking the national trend."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1z98263723","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4wact5786","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across this territory are thriving. Fulwood and Penwortham are Preston''s premium family suburbs, while Chorley and Buckshaw Village attract young families looking for new-build homes and good schools. These are parents who are building their lives in the area and are deeply invested in their local communities. The mix of established Preston families and new arrivals in Buckshaw creates a dynamic, growing market."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dpvvu63739","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3brt65788","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Preston and Chorley, and independent baby classes operate from venues throughout the territory. Family centres, community halls, and church venues provide a steady calendar of baby and toddler sessions. The growing population means new classes are opening regularly to meet demand."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ewtak63745","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wgnfd5790","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Central Lancashire''s growing birth rates set it apart from many other North West territories. The combination of Preston''s city infrastructure, Chorley''s family-friendly character, and Buckshaw Village''s explosive growth creates a territory that''s expanding year on year. For a Memory Catcher looking to build something sustainable, the trajectory here is exciting."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Lancashire Central region covers Preston, Chorley, Leyland, Buckshaw Village, Fulwood, and Penwortham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"xdnzf28384","nodes":[{"id":"9csml28385","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7v5uz13314","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Preston and Chorley"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"8u9ns28387","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"m3un213316","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"l6fyq28389","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"uxjvx13318","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family centres across Lancashire"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"upvuv28391","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ppq9813320","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"wgfon28393","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mjotz13322","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Central Lancashire''s family communities are growing and well-connected. The mix of established residents and new arrivals creates a welcoming environment where a Memory Catcher can build a strong reputation quickly.', null, 'Baby Keepsake Franchise Opportunity in Preston and Chorley', 'Start a flexible Memory Catcher franchise across Preston and Chorley in Lancashire. Capture baby handprints and footprints locally with full training, support, and a protected region.', 53.71, -2.67, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('northampton-milton-keynes', 'Northampton and Milton Keynes', 'Northampton and Milton Keynes', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across two of England''s fastest-growing family towns.', 'Northampton, Milton Keynes, Newport Pagnell, Olney, Towcester, Brackley', 'Two of England''s fastest-growing towns, 520K+ combined, young family demographics, continuous housing growth.', 'NCT Northampton and Milton Keynes, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"71ned8962","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Milton Keynes is one of the fastest-growing towns in England, with a population past 290,000 and a young profile driven by London families relocating. Northampton adds 230,000+ with established communities. Together they represent one of the strongest South Midlands family markets."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3sxgq8964","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0aqxt8965","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Milton Keynes attracts young families looking for modern housing and an affordable alternative to London. Northampton''s established communities provide depth and stability. Both towns have strong community infrastructure."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p00wc8967","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4v5cz8968","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across both towns. Milton Keynes has seen rapid expansion of baby class providers. Community centres, family hubs, and church halls provide a full calendar of sessions."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j95cz8970","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lms4h8971","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The growth trajectory sets this territory apart. Milton Keynes is adding thousands of new families every year, meaning the territory''s potential is expanding continuously."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Northampton and Milton Keynes region covers Northampton, Milton Keynes, Newport Pagnell, Olney, Towcester, and Brackley. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"aip8032644","nodes":[{"id":"2q8tr32645","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yrzhw16758","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Northampton and Milton Keynes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sxeng32647","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cv98c16760","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"srlv132649","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"a9x0k16762","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jbvpm32651","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d1nmm16764","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"v3jvx32653","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o7b3h16766","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Milton Keynes and Northampton are growing and well-connected.', null, 'Baby Keepsake Franchise Opportunity in Northampton and Milton Keynes', 'Start a flexible Memory Catcher franchise across Northampton and Milton Keynes. Capture baby handprints and footprints across two of England''s fastest-growing towns with full training and support.', 52.14, -0.83, 520000)
