gTop":"0px"},"id":"m7qok15544","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yu9dj15545","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Norfolk runs occasional groups. Independent baby classes operate from community centres and family hubs."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hl9fy15547","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"m5j7x15548","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"West Norfolk is a character territory where community warmth and Royal prestige combine. Works well as either full-time or part-time."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your West Norfolk region covers King''s Lynn, Downham Market, Hunstanton, Swaffham, Dereham, and Fakenham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"bq20m58125","nodes":[{"id":"19xih58126","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pwv7p58043","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Norfolk"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ovdha58128","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0ltbf58048","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rg5yk58130","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style"