insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('enfield-north-london', 'Enfield', 'Enfield and North London Borders', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North London''s family-rich borders.', 'Enfield Town, Southgate, Winchmore Hill, Potters Bar, Cheshunt, Waltham Abbey', '350K+ North London borders, premium Southgate and Winchmore Hill, strong family demographics, village feel.', 'NCT Enfield, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6mz8r13023","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Enfield and the North London borders have a combined population exceeding 350,000. Southgate and Winchmore Hill are premium family areas. The territory straddles the London-Hertfordshire border, capturing families from both sides."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mhrht13025","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rkc1u13026","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Southgate and Winchmore Hill attract affluent professional families. Cheshunt and Waltham Abbey provide growing suburban communities. The area benefits from good transport links while maintaining a village feel."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nyyuc13028","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"urvwg13029","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Enfield. Independent baby classes operate throughout. The territory''s accessibility keeps sessions within easy reach."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3y4k213031","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wkscs13032","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This North London borders territory offers premium family suburbs with a community feel that''s harder to find in inner London."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Enfield and North London Borders region covers Enfield Town, Southgate, Winchmore Hill, Potters Bar, Cheshunt, and Waltham Abbey. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"dflrb37413","nodes":[{"id":"zotsv37414","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5sq1b20757","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Enfield"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"clxsn37416","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gz3v020759","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ruvnf37418","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tt1si20761","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"v30xa37420","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gv7f520763","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cp78b37422","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jqx3d20765","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The North London borders combine suburban space with urban accessibility.', null, 'Baby Keepsake Franchise Opportunity in Enfield', 'Start a flexible Memory Catcher franchise across Enfield and North London''s borders. Capture baby handprints and footprints locally with full training and support.', 51.655, -0.075, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('camden-haringey', 'Camden and Haringey', 'London: Camden and Haringey', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North London''s eclectic, family-friendly boroughs.', 'Camden, Haringey, Hampstead, Crouch End, Muswell Hill, Highgate, Hornsey', 'Premium North London boroughs, Hampstead ultra-premium pricing, thriving Crouch End and Muswell Hill family communities, strong baby class infrastructure.', 'NCT Camden and Haringey, multiple independent baby class providers, family hubs', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dl0ly1309","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North London''s Camden and Haringey boroughs offer a unique blend of premium family areas and vibrant urban communities. From the leafy streets of Hampstead and Highgate, where some of London''s wealthiest families reside, to the creative, community-minded neighbourhoods of Crouch End and Muswell Hill, this territory spans a broad and affluent demographic. Haringey alone has a population exceeding 270,000 with a young median age and strong birth rates."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rf5mi1311","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gkfqv1312","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Crouch End and Muswell Hill have become two of North London''s most sought-after family areas. The independent high streets, excellent schools, and strong community networks attract young professionals who are putting down roots and starting families. These are parents who value handcrafted, meaningful products and who invest in quality experiences for their children. Hampstead adds an ultra-premium pocket where average order values run significantly higher."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d2mej1314","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hv4n01315","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is very active across both boroughs with well-attended antenatal and postnatal groups. A wide range of independent baby classes run weekly from venues across the territory, including baby sensory, music, yoga, and development sessions. The Crouch End and Muswell Hill baby class scene is particularly busy, with multiple sessions running from church halls, community centres, and private studios throughout the week."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lj56c1317","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2qbdq1318","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory combines the premium pricing potential of Hampstead and Highgate with the volume and community warmth of Crouch End and Muswell Hill. The result is a balanced territory where high average order values and consistent footfall work together to create strong earning potential."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Camden and Haringey region covers Camden, Haringey, Hampstead, Crouch End, Muswell Hill, Highgate, and Hornsey. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"eevnu25369","nodes":[{"id":"tn8xe25370","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rr6vg10974","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Camden and Haringey"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"o5slu25372","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v7qwx10976","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"3428625374","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n4udq10978","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pu96325376","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u0fiz10980","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xa9ud25378","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cty1l10982","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Crouch End, Muswell Hill, and Hampstead are among the most active and well-connected in London. Class leaders are trusted voices, and recommendations flow naturally through established parent networks.', null, 'Baby Keepsake Franchise Opportunity in Camden and Haringey', 'Start a flexible Memory Catcher franchise across Camden and Haringey. Capture baby handprints and footprints in North London with full training, support, and a protected region.', 51.57, -0.135, 480000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('liverpool', 'Liverpool', 'Liverpool', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the UK''s most community-driven cities.', 'Liverpool city centre, South Liverpool, Aigburth, Allerton, Mossley Hill, Woolton, Childwall', '500K+ population, existing Established baby class partners, legendary community spirit, strong South Liverpool family areas, Scouse word-of-mouth culture.', 'Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c4h0k2917","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Liverpool has a population exceeding 500,000 and a community spirit that''s unmatched anywhere in the country. The city''s strong sense of identity, warmth, and loyalty to local businesses creates the perfect environment for a Memory Catcher. When Scousers find something they love, they tell everyone about it, and that word-of-mouth culture is gold for a franchise built on trust and genuine connections."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f246w2919","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nlybo2920","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"South Liverpool is the family heartland of the city. Aigburth, Allerton, Mossley Hill, and Woolton are popular with young professional families drawn by tree-lined streets, good schools, and a strong community feel. Childwall and Gateacre add further depth with established family communities. These are parents who care about meaningful experiences and who invest in quality products for their children."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bha7c2922","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gh5uf2923","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections for a Memory Catcher. NCT groups are active across the city, and a range of independent baby sensory, music, and development classes run weekly. Liverpool''s community infrastructure is strong, with family centres, church halls, and community venues providing a full calendar of baby and toddler sessions."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fy8hz2925","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"196lj2926","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Liverpool offers a rare combination of volume, community warmth, and existing baby class partnerships. The city''s famous loyalty means that once you''re established as the local Memory Catcher, the community supports you passionately. Add in the existing baby class partnership and you''re not starting cold, you''re stepping into a city that''s ready for you."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Liverpool region covers Liverpool city centre, South Liverpool, Aigburth, Allerton, Mossley Hill, Woolton, and Childwall. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"gyfn227309","nodes":[{"id":"euhq727310","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jja5o12589","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"retnh27312","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o23ge12591","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Liverpool"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"n5yvm27314","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"65vfn12593","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"uy04d27316","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y2nwi12595","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kc9aa27318","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gaonz12597","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Liverpool''s community spirit is legendary, and it extends right into the baby class world. Class leaders know each other, parents talk to each other, and when a local business earns trust, the whole community gets behind it. That''s the Scouse way.', null, 'Baby Keepsake Franchise Opportunity in Liverpool', 'Start a flexible Memory Catcher franchise in Liverpool. Capture baby handprints and footprints across the city with full training, support, and a protected region.', 53.41, -2.98, 500000)
