tAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t420021839","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"allse38555","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v09vw21841","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7r2fy38557","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sn7x721843","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Bedfordshire''s communities are diverse, growing, and family-focused.', null, 'Baby Keepsake Franchise Opportunity in Bedford and Luton', 'Start a flexible Memory Catcher franchise across Bedfordshire. Capture baby handprints and footprints locally with full training and support.', 52.01, -0.45, 400000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('east-sussex', 'East Sussex', 'East Sussex: Eastbourne and Hastings', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across East Sussex''s coastal family communities.', 'Eastbourne, Hastings, Bexhill, Crowborough, Uckfield, Hailsham', '550K+ county, Hastings creative regeneration, Crowborough High Weald premium, coastal lifestyle, growing communities.', 'NCT East Sussex, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"q5umm14805","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"East Sussex has a population exceeding 550,000. The coastal towns of Eastbourne and Hastings anchor the territory. Crowborough and Uckfield add inland family communities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xizvs14807","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ws39614808","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hastings'' regeneration is attracting creative families. Crowborough in the High Weald is a premium inland pocket. Eastbourne provides established family infrastructure."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hz7u814810","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xsz7f14811","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across East Sussex. Independent baby classes operate from venues throughout. The territory spans coast and countryside."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p6j1d14813","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rzu1f14814","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"East Sussex offers coastal character, High Weald premium pockets, and growing family communities. The regeneration of Hastings brings fresh energy."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your East Sussex region covers Eastbourne, Hastings, Bexhill, Crowborough, Uckfield, and Hailsham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"xboct56690","nodes":[{"id":"pd50u56691","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mt35m56608","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT East Sussex"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jo83v56693","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"siae756613","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4zovn56695","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ngxf456618","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"nk2xc56697","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e8q2b56623","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"algyo56699","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6xbsm56628","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'East Sussex''s communities blend coastal warmth with countryside charm.', null, 'Baby Keepsake Franchise Opportunity in East Sussex', 'Start a flexible Memory Catcher franchise across East Sussex. Capture baby handprints and footprints locally with full training and support.', 50.83, 0.45, 550000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('antrim', 'Antrim', 'Antrim and East Antrim', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across County Antrim''s coastal and countryside communities.', 'Antrim, Ballymena, Larne, Carrickfergus, Newtownabbey, Glengormley', '300K+ territory, Belfast-adjacent Newtownabbey, Antrim coast character, Ballymena market town.', 'Independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0mfd015297","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Antrim and East Antrim have a combined population exceeding 300,000. Newtownabbey and Glengormley sit on Belfast''s northern doorstep with growing family suburbs."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f22fa15299","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d67my15300","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Antrim coast from Carrickfergus to Larne adds scenic family communities. Ballymena is one of Northern Ireland''s largest market towns. Newtownabbey provides Belfast-adjacent volume."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dmv5r15302","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8qtsg15303","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes and community groups operate from venues across the territory. Community centres and church halls are the main venues."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j80xm15305","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oiwc915306","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Antrim offers a balanced territory with Belfast-adjacent suburbs and distinctive Antrim coast communities. Note: different legal frameworks may apply for franchise agreements in Northern Ireland."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Antrim and East Antrim region covers Antrim, Ballymena, Larne, Carrickfergus, Newtownabbey, and Glengormley. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6mwpb57671","nodes":[{"id":"lzkut57672","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r92mx57589","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"yz4t357674","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2crlw57594","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"nchkl57676","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ec1n357599","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"8a76o57678","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zbbsi57604","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Church groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"voy2f57680","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tvl6t57609","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Mother and toddler groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Antrim''s communities are warm and well-connected.', null, 'Baby Keepsake Franchise Opportunity in County Antrim', 'Start a flexible Memory Catcher franchise across County Antrim. Capture baby handprints and footprints locally with full training and support.', 54.78, -6, 300000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('sheffield', 'Sheffield', 'Sheffield', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of Yorkshire''s largest and greenest cities.', 'Sheffield city centre, Ecclesall, Dore, Crookes, Hillsborough, Chapeltown', 'UK''s 5th largest city (550K+), young demographics, premium Ecclesall and Dore suburbs, greenest city in England.', 'NCT Sheffield, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8njuz7655","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Sheffield is the UK''s fifth largest city with a population exceeding 550,000. Two universities feed a steady pipeline of young professionals who stay to start families. The result is a young, educated population with strong family formation rates."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yb2t37657","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ujjpo7658","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities in Sheffield''s south west are where the premium market sits. Ecclesall Road, Dore, and Fulwood attract affluent professional families. The city''s strong independent culture means parents actively support local businesses and value handcrafted products."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bsm3r7660","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cl92k7661","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is very active across Sheffield. A wide range of independent baby sensory, music, yoga, and development classes run from venues throughout the city. The south west is particularly well-served by premium providers."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i427p7663","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o1w277664","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Sheffield offers the scale of a major city with a community feel that''s rare for its size. Young demographics, strong family suburbs, and an independent culture make it one of Yorkshire''s most compelling territories."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Sheffield region covers Sheffield city centre, Ecclesall, Dore, Crookes, Hillsborough, and Chapeltown. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"hpxaa48209","nodes":[{"id":"mhbsa48210","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lhxo648107","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Sheffield"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"q9o4i48212","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"60izw48112","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"q775e48214","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rf03748117","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"m0iia48216","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t74w548122","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qbszj48218","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"97hew48127","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Sheffield''s parenting community is warm, creative, and deeply connected. The city''s strong independent culture creates the perfect environment for a Memory Catcher.', null, 'Baby Keepsake Franchise Opportunity in Sheffield', 'Start a flexible Memory Catcher franchise in Sheffield. Capture baby handprints and footprints across one of Yorkshire''s largest cities with full training and support.', 53.38, -1.47, 550000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('cambridge', 'Cambridge', 'Cambridge and South Cambridgeshire', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of England''s most innovative and family-focused cities.', 'Cambridge city centre, Trumpington, Cherry Hinton, Ely, Newmarket, Saffron Walden', 'Silicon Fen tech wealth, world-famous university, international family community, 350K+ territory, exceptional average order value potential.', 'NCT Cambridge, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xay9f6789","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cambridge is one of the wealthiest and most highly educated cities in England, with a thriving tech sector (Silicon Fen) that attracts brilliant young professionals from around the world. Many of these professionals are now starting families, creating a premium, international market for meaningful baby keepsakes. The city''s population has grown rapidly and the wider territory exceeds 350,000 residents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3qtfx6791","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dx3q96792","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family culture in Cambridge mirrors the city''s character, engaged, thoughtful, and quality-conscious. Parents here research products carefully, invest in things they believe in, and form strong community bonds through baby classes and university-linked parent groups. The international dimension is significant, with many families far from home and particularly drawn to tangible keepsakes of their children''s early moments."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j72da6794","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j45dz6795","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs well-attended groups across Cambridge, and independent baby classes thrive across the city and surrounding areas. The baby class scene here is premium and vibrant, with a packed weekly calendar. University-linked parent groups add a unique dimension that few other territories can offer."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xzxif6797","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"04m2u6798","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cambridge is a premium territory with exceptional demographics. The combination of tech industry wealth, university prestige, and an international family community creates a market where average order values are among the highest outside London. For a Memory Catcher seeking an intellectually engaged, quality-driven market, Cambridge is outstanding."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Cambridge and South Cambridgeshire region covers Cambridge city centre, Trumpington, Cherry Hinton, Ely, Newmarket, and Saffron Walden. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"spm7330023","nodes":[{"id":"9ybm430024","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ghjbn14693","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Cambridge"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"426fj30026","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hcp7d14695","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"wax4a30028","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ci0op14697","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"University parent groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"iau6k30030","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ar7kd14699","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ooy9c30032","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qxzly14701","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Cambridge''s parenting community is engaged, international, and quality-driven. The university and tech industry create uniquely diverse parent networks where a Memory Catcher can build a premium reputation.', null, 'Baby Keepsake Franchise Opportunity in Cambridge', 'Start a flexible Memory Catcher franchise across Cambridge. Capture baby handprints and footprints in one of England''s most innovative cities with full training, support, and a protected region.', 52.15, 0.11, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('croydon', 'Croydon', 'London: Croydon', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of London''s largest and most family-rich boroughs.', 'Croydon, South Croydon, Purley, Coulsdon, Thornton Heath, Norbury', 'One of London''s most populous boroughs (390K+), high birth rates, diverse family communities, strong baby class infrastructure, significant regeneration investment.', 'NCT Croydon, multiple independent baby class providers, family centres and children''s centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fvwnt2045","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Croydon is one of the most populous boroughs in London with over 390,000 residents, and its young, diverse population generates one of the highest birth rates in the capital. The borough has undergone significant regeneration in recent years, with major investment transforming the town centre whilst maintaining the suburban family character that defines areas like Purley, South Croydon, and Coulsdon."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r874l2047","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pbtsa2048","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across Croydon are diverse and active. From the more affluent southern areas of Purley and Coulsdon, where leafy streets and good schools attract professional families, to the vibrant, multicultural communities of Thornton Heath and Norbury, parents across the borough share a common desire to celebrate their children''s milestones. The cultural diversity here is a genuine strength, with families from all backgrounds valuing handcrafted keepsakes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"q01ew2050","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b0tnp2051","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Croydon are well-established. NCT runs active groups across the borough, and a range of independent baby sensory, music, and development classes operate from community centres, church halls, and family hubs throughout the area. Children''s centres across the borough provide additional touchpoints for connecting with new and expectant parents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p3bn72053","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t23vw2054","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Croydon''s strength is in its scale. The sheer number of new babies born in the borough each year provides a consistent and substantial customer base. While it may not carry the ultra-premium pricing of inner London, the volume and the borough''s well-connected family infrastructure make this a territory where a committed Memory Catcher can build a strong, sustainable income."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Croydon region covers Croydon, South Croydon, Purley, Coulsdon, Thornton Heath, and Norbury. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"14y9l26329","nodes":[{"id":"n6bzx26330","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ogzrd11706","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Croydon"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"vzhf226332","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qe1j211708","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"mttul26334","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rifxm11710","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xajh326336","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lku0s11712","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pk34926338","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wcyd611714","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Croydon''s family communities are diverse, welcoming, and well-connected through a strong network of baby classes, family centres, and community groups. The borough''s scale means there''s always a warm room to walk into.', null, 'Baby Keepsake Franchise Opportunity in Croydon', 'Start a flexible Memory Catcher franchise in Croydon. Capture baby handprints and footprints across one of London''s largest family boroughs with full training, support, and a protected region.', 51.37, -0.1, 390000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('kensington-chelsea-hammersmith', 'Kensington, Chelsea and Fulham', 'London: Kensington and Chelsea, Hammersmith and Fulham', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across some of London''s most exclusive family neighbourhoods.', 'Kensington, Chelsea, Hammersmith, Fulham, Parsons Green, South Kensington', 'London''s most exclusive family boroughs, ultra-premium average order values, international family community, boutique territory with exceptional per-session revenue.', 'The Bump Class (Parsons Green, South Kensington), premium private antenatal classes, NCT groups', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ky36x210","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Kensington and Chelsea is one of the most exclusive boroughs in London, with a median household income above £56,000 and a reputation for premium everything. Fulham has transformed over the past decade into one of London''s most popular family neighbourhoods, with young professionals trading zone one flats for Victorian terraces along the Munster Road corridor. Together, these boroughs represent the highest-value boutique territory in the Memory Catcher network."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3m21f219","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4s0a7212","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This is a quality-over-quantity region. Birth volumes are lower than other London territories, Kensington and Chelsea is actually the smallest borough by population, but the parents here invest at a level that few other areas can match. When families in South Kensington or Parsons Green decide to commission a keepsake, they choose the premium option without hesitation. That translates directly into higher average order values per session."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n8lbm225","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v3wv5214","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The baby class offering here is distinctly premium. The Bump Class operates popular sessions from Parsons Green and South Kensington, drawing in affluent first-time parents who are willing to invest in their baby''s early experiences. NCT groups run across both boroughs, and a range of private antenatal and postnatal classes cater to the international family community that defines this part of London."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v8gnt231","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ng85v216","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes this region unique is the international dimension. A significant proportion of parents in Kensington and Chelsea are international families who particularly value tangible, physical keepsakes of their baby''s earliest days. The Memory Catcher service resonates deeply with families who may not have extended family nearby and want to preserve every precious moment."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Kensington, Chelsea, Hammersmith and Fulham region covers Kensington, Chelsea, Hammersmith, Fulham, Parsons Green, and South Kensington. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"h8syd24212","nodes":[{"id":"l4g0024213","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"408qc9992","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Bump Class (Parsons Green and South Kensington)"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5whpd24215","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"99s4y9994","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Kensington and Chelsea"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ybvor24217","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"063ja9996","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Hammersmith and Fulham"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"78rv424219","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qrkzo9998","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium private antenatal providers"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4tjuj24221","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wwovt10000","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes and family groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting community here operates through trusted recommendations. Class leaders and antenatal providers have established relationships with their clients, and being introduced through those channels gives you immediate credibility with parents who expect the best.', null, 'Baby Keepsake Franchise, Kensington & Chelsea London', 'Start a flexible Memory Catcher franchise across Kensington, Chelsea, and Fulham. Capture baby handprints and footprints in London''s most exclusive family neighbourhoods with full training and support.', 51.49, -0.205, 330000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('oldham-rochdale', 'Oldham and Rochdale', 'Oldham and Rochdale', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across north east Greater Manchester''s family-rich communities.', 'Oldham, Rochdale, Saddleworth, Royton, Shaw, Heywood, Middleton', '430K+ combined population, existing Established baby class partners, high birth rates, Saddleworth premium pocket, strong community values.', 'Established baby class partners, Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dbe965321","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Oldham and Rochdale have a combined population exceeding 430,000 and are home to some of Greater Manchester''s youngest demographics. Both towns have strong family traditions, with multicultural communities where family is central to everything. The birth rates across these boroughs are among the highest in the region, providing a consistent and substantial customer base for a Memory Catcher."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ptu5h5323","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wnop25324","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes these communities special is their warmth. From the Pennine-edge villages of Saddleworth, where affluent families enjoy a semi-rural lifestyle, to the vibrant multicultural communities of Oldham and Rochdale town centres, these are places where people look out for each other. Parents here value genuine connections and trust, and they support local businesses that earn it."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"unrfx5326","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fdzfe5327","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections for a Memory Catcher from day one. NCT groups are active in the area, and independent baby classes run from community centres, church halls, and family hubs throughout both towns. The community infrastructure here is strong and well-established."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w43bd5329","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1vsuf5330","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The combination of high birth rates, existing baby class partnerships, and an accessible buy-in price makes this an attractive territory. Saddleworth adds a premium pocket with higher average order values, while the broader communities across both towns provide the volume that sustains a full-time franchise."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Oldham and Rochdale region covers Oldham, Rochdale, Saddleworth, Royton, Shaw, Heywood, and Middleton. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"acroq45291","nodes":[{"id":"cghnq45292","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pl1x045216","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"aky3945294","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kwjn545221","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Oldham and Rochdale"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7q2un45296","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"z58vu45226","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"b7y2b45298","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9fj3r45231","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Oldham and Rochdale''s communities are warm, close-knit, and loyal. Existing baby class partnerships provides immediate warm connections, and the strong family values across both towns create the perfect environment for a Memory Catcher to thrive.', null, 'Baby Keepsake Franchise Opportunity in Oldham and Rochdale', 'Start a flexible Memory Catcher franchise across Oldham and Rochdale with Established baby class partners', 53.58, -2.14, 430000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('dundee', 'Dundee', 'Dundee and Angus', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Scotland''s City of Discovery.', 'Dundee city centre, Broughty Ferry, Arbroath, Montrose, Forfar', 'V&A Dundee regeneration city, Broughty Ferry premium coast, university pipeline, 265K+ combined population, growing family market.', 'NCT Dundee, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"orlay6310","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Dundee has undergone a remarkable transformation, anchored by the V&A Dundee museum and wider waterfront regeneration. The city has a population of around 150,000, with Angus adding a further 115,000 through Arbroath, Montrose, and the surrounding towns. The university feeds a pipeline of young professionals, and the city''s revitalised identity is attracting creative families who see Dundee''s potential."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"aexy96312","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dn14j6313","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Broughty Ferry is the premium pocket of this territory, a charming seaside suburb with independent shops, excellent schools, and an affluent family community. The wider Dundee area brings volume and the energy of a regenerating city. Angus adds traditional Scottish market towns with strong family values and community bonds."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8hust6315","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qhy506316","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups in Dundee, and independent baby classes operate from venues across the territory. The baby class scene is growing alongside the city''s regeneration, with new providers and venues opening regularly. Community centres, church halls, and family hubs provide further opportunities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p6j6k6318","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"uaytk6319","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Dundee works well as either a full-time or part-time territory. Broughty Ferry''s premium families anchor the market, and the city''s regeneration is creating a growing customer base. The compact geography and strong community culture make this a manageable, rewarding territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Dundee and Angus region covers Dundee city centre, Broughty Ferry, Arbroath, Montrose, and Forfar. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"ai71s29425","nodes":[{"id":"3hd8v29426","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9vvrp14187","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Dundee"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"1cdaf29428","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4vhrz14189","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"u091029430","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"odk6j14191","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5o1n729432","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5sr5014193","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"djzm129434","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fgs9q14195","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Dundee''s regeneration has energised the city''s family communities. Broughty Ferry''s engaged parent network and the growing city-centre community create a warm foundation for a Memory Catcher.', null, 'Baby Keepsake Franchise Opportunity in Dundee', 'Start a flexible Memory Catcher franchise across Dundee and Angus. Capture baby handprints and footprints in Scotland''s City of Discovery with full training, support, and a protected region.', 56.52, -2.95, 265000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bromley-bexley', 'Bromley and Bexley', 'London: Bromley and Bexley', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across South East London''s established suburban boroughs.', 'Bromley, Bexley, Chislehurst, Orpington, Beckenham, Sidcup, Bexleyheath', 'London''s largest borough (Bromley), established suburban family communities, strong baby class infrastructure, high birth volumes across both boroughs.', 'NCT Bromley and Bexley, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fgenk1788","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bromley is the largest borough in London by area, and together with Bexley, this territory covers a substantial swathe of outer South East London. These are the suburbs where families come to stay, drawn by larger homes, excellent schools, good transport links, and a sense of community that''s harder to find closer to the centre. Bromley alone has a population exceeding 330,000, with Bexley adding a further 250,000."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wgtj21790","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gb1wa1791","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across Beckenham, Chislehurst, and Bromley town are well-established and active. These are neighbourhoods where parents attend baby classes consistently, form lasting social groups, and support local businesses they trust. Bexleyheath and Sidcup add further volume with growing family populations and strong community infrastructure. The suburban setting means parents are rooted in their area and build deep local connections."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vh9ln1793","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5d4dd1794","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across both boroughs, and independent baby sensory, music, and development classes operate from venues throughout the territory. Church halls, community centres, and family hubs provide a steady calendar of baby and toddler sessions. The territory''s size means there are always new classes and venues to explore."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1iwkt1796","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bgthq1797","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Outer London territories like Bromley and Bexley offer a compelling combination for a Memory Catcher, strong family demographics, community-minded parents, and the consistency that comes from established suburban neighbourhoods. The volume is there, the parents are engaged, and the community infrastructure supports a full-time franchise."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bromley and Bexley region covers Bromley, Bexley, Chislehurst, Orpington, Beckenham, Sidcup, and Bexleyheath. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"yzvr725931","nodes":[{"id":"bauco25932","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2rczo11467","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Bromley and Bexley"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5o2ws25934","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"la86911469","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rjdsc25936","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"elksr11471","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"mr0d725938","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s44le11473","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"74zux25940","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"64wit11475","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The suburban family communities across Bromley and Bexley are warm, loyal, and well-connected. Parents here build long-term relationships with local businesses, and once you''re known and trusted, the referrals follow naturally.', null, 'Baby Keepsake Franchise Opportunity in Bromley and Bexley', 'Start a flexible Memory Catcher franchise across Bromley and Bexley. Capture baby handprints and footprints in South East London with full training, support, and a protected region.', 51.42, 0.09, 580000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('exeter', 'Exeter', 'Exeter and East Devon', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Devon''s thriving capital city.', 'Exeter, Exmouth, Topsham, Sidmouth, Honiton, Crediton', 'Devon''s capital, university pipeline, Topsham premium pocket, 350K+ territory, strong South West independent culture.', 'NCT Exeter, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e78r610903","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Exeter is Devon''s capital with one of the most liveable settings in the South West. The university feeds a steady pipeline of young families. The wider territory exceeds 350,000 residents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bmii710905","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2i6sl10906","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Exeter''s family communities are active, engaged, and independent-minded. Topsham adds a premium pocket. The East Devon coastal towns bring distinctive charm."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4cfnq10908","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6xdsc10909","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Exeter and East Devon. Independent baby classes operate throughout. The baby class scene is well-established in Exeter and growing wider."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6o1q310911","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4lq1w10912","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Exeter is the anchor territory for Devon, combining a thriving city market with broader East Devon family communities."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Exeter and East Devon region covers Exeter, Exmouth, Topsham, Sidmouth, Honiton, and Crediton. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6hq2a34969","nodes":[{"id":"jlwtb34970","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n8t4918732","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Exeter"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"yc0au34972","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3sn8618734","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0145r34974","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jbtnt18736","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xtsnl34976","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9ayn218738","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ca31t34978","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h1ypz18740","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Exeter''s parenting community is warm, creative, and well-connected.', null, 'Baby Keepsake Franchise Opportunity in Exeter', 'Start a flexible Memory Catcher franchise across Exeter and East Devon. Capture baby handprints and footprints locally with full training and support.', 50.73, -3.4, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('cheshire-west', 'Chester and Northwich', 'Cheshire West: Chester and Northwich', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Cheshire''s historic western territory.', 'Chester, Northwich, Winsford, Ellesmere Port, Neston, Frodsham', 'Historic Chester premium market, existing baby class partnership, growing Northwich and Winsford communities, strong community infrastructure.', 'Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v2d1y5506","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Chester is one of the most beautiful cities in England, and its family demographics match its appeal. The city and its surrounding suburbs attract professional families drawn by excellent schools, historic character, and a quality of life that consistently ranks among the best in the country. Northwich, Winsford, and the wider Cheshire West area add volume with established family communities and competitive housing costs that attract young families moving out from Manchester and Liverpool."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g4yz064261","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9lwcv5508","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family culture across Cheshire West is warm and community-focused. Chester''s well-heeled suburbs drive premium pricing, while the towns across the wider territory provide a broader base of engaged parents. The independent shopping culture on Chester''s rows and the strong community identities of the surrounding towns create natural networks where recommendations travel fast."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4w3u064267","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iht1x5510","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections for a Memory Catcher. NCT groups run across the area, and independent baby classes operate from venues throughout the territory. Chester''s baby class scene is well-established, and the growing populations across Northwich and Winsford mean new classes are opening regularly."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jp6n264273","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yw5eo5512","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cheshire West offers the combination of Chester''s premium market with the volume and community warmth of the wider area. The existing baby class partner relationship provides warm introductions from day one, and the territory''s balanced mix of demographics creates consistent earning potential throughout the year."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Cheshire West region covers Chester, Northwich, Winsford, Ellesmere Port, Neston, and Frodsham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"w37vh28828","nodes":[{"id":"7kdjv28829","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zf5tc13692","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ud7h428831","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j71mj13694","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Chester and Cheshire West"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"czsae28833","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iw4sr13696","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"biivs28835","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bub8f13698","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xivxt28837","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"an95h13700","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Chester and Cheshire West are warm, well-connected, and loyal. Existing baby class partnerships provides a warm start, and the mix of city and town communities offers variety and depth.', null, 'Baby Keepsake Franchise Opportunity in Chester and Northwich', 'Start a flexible Memory Catcher franchise across Chester and Cheshire West with baby class partnerships in place. Capture baby handprints and footprints locally with full training and support.', 53.22, -2.72, 360000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('mid-ulster', 'Mid Ulster', 'Mid Ulster and Armagh', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Mid Ulster''s close-knit communities.', 'Craigavon, Armagh, Dungannon, Cookstown, Lurgan, Portadown', 'Highest birth rates in UK, deeply family-oriented culture, 300K+ territory, strong community bonds.', 'Independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qscio15175","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Mid Ulster and Armagh have a combined population exceeding 300,000 with consistently high birth rates. This is one of the youngest demographic areas in the UK."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lhfhg15177","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cz7h915178","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"These are deeply family-oriented communities where babies are celebrated and extended family networks are strong. That cultural embrace of family life translates into natural demand for keepsake services."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2tsbe15180","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kvnmd15181","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes and community groups operate from venues across the territory. Community centres and church halls provide the backbone of the baby class infrastructure."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dq32u15183","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fy8bx15184","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Mid Ulster''s high birth rates and family-first culture create a market with exceptional volume potential. Note: different legal frameworks may apply for franchise agreements in Northern Ireland."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Mid Ulster and Armagh region covers Craigavon, Armagh, Dungannon, Cookstown, Lurgan, and Portadown. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6dnhl57409","nodes":[{"id":"zzncl57410","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3ydmu57306","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ug3u157412","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t4tjy57311","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jka5o57414","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zdyoy57316","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"z2uij57416","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qaupw57321","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Church groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cfb0b57418","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t0qyw57326","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Mother and toddler groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Mid Ulster''s communities are deeply family-oriented with strong extended family networks.', null, 'Baby Keepsake Franchise Opportunity in Mid Ulster', 'Start a flexible Memory Catcher franchise across Mid Ulster and Armagh. Capture baby handprints and footprints locally with full training and support.', 54.48, -6.75, 300000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('stockport-tameside', 'Stockport and Tameside', 'Stockport and Tameside', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across south east Greater Manchester''s thriving family communities.', 'Stockport, Tameside, Marple, Bramhall, Cheadle, Ashton-under-Lyne, Hyde', '520K+ combined population, existing Established baby class partners, premium Bramhall/Marple/Cheadle suburbs, strong community infrastructure.', 'Established baby class partners, Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"86yan3286","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Stockport and Tameside sit on the south eastern edge of Greater Manchester with a combined population exceeding 520,000. Stockport in particular has experienced significant regeneration, with investment transforming the town centre while the surrounding suburbs of Marple, Bramhall, and Cheadle have long been among the most desirable family areas in Greater Manchester. These are communities where families put down roots and stay."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"il4qk3288","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"43hu93289","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family demographics here are strong. Bramhall, Cheadle Hulme, and Marple attract young professionals who want excellent schools and a village feel within easy reach of Manchester. Tameside adds volume through Ashton-under-Lyne, Hyde, and the surrounding towns, where strong community identities and family values run deep. Parents across both areas value quality, meaningful products for their children."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lnlhs3291","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xp6vk3292","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory benefits from existing Established baby class partners, providing warm connections from day one. NCT groups are active across the area, and independent baby sensory, music, and development classes operate from venues throughout the territory. The baby class scene here is well-established and growing."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"enkbz3294","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4ua6x3295","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The combination of baby class partnerships, affluent family suburbs in Stockport, and the volume across Tameside makes this a compelling territory. A Memory Catcher here has access to warm rooms from day one, premium pockets for higher order values, and a combined population that supports a full-time franchise."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Stockport and Tameside region covers Stockport, Tameside, Marple, Bramhall, Cheadle, Ashton-under-Lyne, and Hyde. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"ntpve27972","nodes":[{"id":"p4yp727973","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0grve12943","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"i4l6727975","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"epr5u12945","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Stockport and Tameside"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"1ll5m27977","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qxbyq12947","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"3ebj827979","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b71nr12949","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The family communities across Stockport and Tameside are well-connected and loyal. Existing baby class partnerships means warm introductions are already possible, and the established baby class networks provide a solid foundation for a Memory Catcher to build from.', null, 'Baby Keepsake Franchise Opportunity in Stockport and Tameside', 'Start a flexible Memory Catcher franchise across Stockport and Tameside with existing Established baby class partners', 53.435, -2.13, 520000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('perth', 'Perth', 'Perth and Kinross', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Scotland''s Fair City.', 'Perth, Crieff, Auchterarder, Blairgowrie, Kinross', 'Scotland''s Fair City, compact rewarding territory, premium Auchterarder, quality of life destination.', 'NCT Scotland, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"egjij13615","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Perth and Kinross has a population of around 155,000. Perth is a compact, attractive city with strong family communities. Auchterarder and Crieff add premium pockets."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"377gm13617","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7jfm413618","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Perth''s family communities are well-connected and community-minded. The area attracts families drawn by quality of life, excellent schools, and access to the countryside."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"egc9g13620","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","t