insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('lancaster-morecambe', 'Lancaster and Morecambe', 'Lancaster and Morecambe', true, '£3,445', 'Part-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North Lancashire''s university city and coast.', 'Lancaster, Morecambe, Carnforth, Garstang, surrounding villages', 'Compact university city, steady young family pipeline, strong independent culture, part-time territory with engaged community.', 'NCT Lancaster, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y64su5930","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lancaster is a compact, characterful university city with a population of around 150,000 across the wider district. Lancaster University feeds a steady stream of young professionals who stay in the area to start families, drawn by the city''s heritage charm, excellent schools, and affordable living. Morecambe adds a coastal dimension with ongoing regeneration attracting new residents to the bay."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cnqm45939","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"opif85932","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The parenting community in Lancaster is active and well-connected for its size. The city''s compact nature means parents quickly find their tribe through baby classes and community groups. The independent culture mirrors what you''d find in much larger cities, with parents actively supporting local, artisan businesses and valuing meaningful products for their children."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"00vgw5945","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gdwz15934","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Lancaster, and independent baby classes operate from venues throughout the area. Community centres, church halls, and family hubs provide regular baby and toddler sessions. The university and hospital also create networks of new parents who are looking for exactly the kind of community connection a Memory Catcher provides."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5twtu5951","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jhzmm5936","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lancaster works well as a part-time territory. The population is smaller than many other regions, but the engaged, community-minded character of the area and the steady flow of new families through the university mean there''s consistent demand. The compact geography keeps travel manageable and efficient."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Lancaster and Morecambe region covers Lancaster, Morecambe, Carnforth, Garstang, and the surrounding villages. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"wpfaf28977","nodes":[{"id":"ly44028978","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"i4h7y13818","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Lancaster"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"f9l8d28980","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1t13513820","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cvbw828982","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"93nux13822","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jdt1p28984","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8pgdc13824","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family centres and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ke5k828986","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zlwxa13826","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"University parent groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Lancaster''s parenting community punches above its weight. The compact city, university presence, and strong independent culture create the kind of close-knit family networks where a Memory Catcher quickly becomes a trusted, familiar face.', null, 'Baby Keepsake Franchise Opportunity in Lancaster and Morecambe', 'Start a flexible Memory Catcher franchise in Lancaster and Morecambe. Capture baby handprints and footprints locally with full training, support, and a protected region.', 54.05, -2.83, 145000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('hillingdon-harrow', 'Hillingdon and Harrow', 'London: Hillingdon and Harrow', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across outer West London''s established family boroughs.', 'Uxbridge, Harrow, Ruislip, Pinner, Northwood, Hayes, Stanmore', 'Outer West London with 550K+ combined population, premium Pinner and Northwood pockets, strong suburban family communities, established baby class infrastructure.', 'NCT Hillingdon and Harrow, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hsb1d2298","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Hillingdon and Harrow form the outer western edge of London, where suburban family life thrives. These boroughs attract families looking for more space, good schools, and a genuine sense of community. Pinner and Northwood are premium pockets with affluent family demographics, while Ruislip and Uxbridge offer strong family communities with a more accessible feel. Together, the boroughs have a combined population exceeding 550,000."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jzgj82300","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8upfd2301","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities here are deeply rooted and active. Parents in Pinner, Northwood, and Stanmore invest in quality products and experiences for their children, while the broader communities across Ruislip, Hayes, and Harrow town bring volume and diversity. The suburban setting means families stay in the area long-term, building the kind of sustained relationships that drive repeat business for a Memory Catcher."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n2oog2303","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3y8nk2304","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is active across both boroughs, and a range of independent baby classes operate from community centres, church halls, and family hubs. The territory benefits from a steady calendar of baby and toddler sessions, with new classes and venues continuing to open as the family population grows."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kl0f42306","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nlda42307","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Outer West London offers a solid foundation for a Memory Catcher. The combination of premium pockets in Pinner and Northwood with the broader family communities across both boroughs creates a territory with consistent demand and a loyal customer base."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Hillingdon and Harrow region covers Uxbridge, Harrow, Ruislip, Pinner, Northwood, Hayes, and Stanmore. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"64pmv26603","nodes":[{"id":"93esz26604","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"an88211947","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Hillingdon and Harrow"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"n534026606","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"m6zdo11949","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"z11zo26608","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1g8uo11951","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"017rv26610","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bl29111953","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xj7eu26612","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rxr1a11955","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The family communities across Pinner, Northwood, and the wider Hillingdon and Harrow area are well-connected and loyal. The suburban setting fosters genuine community bonds that work in a Memory Catcher''s favour.', null, 'Baby Keepsake Franchise Opportunity in Hillingdon and Harrow', 'Start a flexible Memory Catcher franchise across Hillingdon and Harrow. Capture baby handprints and footprints in outer West London with full training, support, and a protected region.', 51.56, -0.41, 550000)
