,"nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"s0n6v30912","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qegqe15432","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"tmrwd30914","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nu4hi15434","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ph97330916","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"804cw15436","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Teesside''s communities are proud and genuine. The Yarm circuit provides premium touchpoints, while the wider networks offer consistent volume.', null, 'Baby Keepsake Franchise Opportunity in Middlesbrough and Stockton', 'Start a flexible Memory Catcher franchise across Teesside. Capture baby handprints and footprints locally with full training, support, and a protected region.', 54.57, -1.23, 500000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('north-tyneside', 'North Tyneside', 'North Tyneside and Northumberland South', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the North East''s coastal family communities.', 'North Shields, Whitley Bay, Tynemouth, Cramlington, Blyth, Ponteland', 'Desirable Whitley Bay coast, existing baby class partnership, growing family suburbs, Ponteland affluent pocket.', 'Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x5dyl7268","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Tyneside and southern Northumberland offer a brilliant mix of coastal living and growing family suburbs. Whitley Bay and Tynemouth have become two of the most desirable family destinations in the North East. Cramlington adds suburban volume with young families drawn by affordable new-build housing."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gniy37270","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9tm427271","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The coastal communities of Whitley Bay and Tynemouth have a special character. The beaches, independent cafes, and community events create a lifestyle that attracts engaged, active parents who value quality products. Ponteland adds an affluent rural pocket to the west."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pd25b7273","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xzahd7274","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing warm connections. NCT runs groups across the area, and independent baby classes operate from venues throughout the territory."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ej85u7276","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qr8257277","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Tyneside offers existing baby class partnerships, a desirable coastal lifestyle, and a growing population. The combination of established communities and new family arrivals creates a dynamic, rewarding territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your North Tyneside region covers North Shields, Whitley Bay, Tynemouth, Cramlington, Blyth, and Ponteland. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"c041o30607","nodes":[{"id":"l85lk30608","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gle0715169","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"mncnc30610","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ygj0t15171","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT North Tyneside"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"3j53a30612","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"87lmu15173","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4q1ed30614","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ojjln15175","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7ibn230616","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nqj0215177","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The coastal communities of North Tyneside are vibrant and welcoming. The baby class partnership provides a warm start.', null, 'Baby Keepsake Franchise Opportunity in North Tyneside', 'Start a flexible Memory Catcher franchise across North Tyneside with baby class partnerships. Capture baby handprints and footprints along the North East coast with full training and support.', 55.05, -1.55, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('leicester', 'Leicester', 'Leicester', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the UK''s most diverse and family-focused cities.', 'Leicester city centre, Oadby, Wigston, Birstall, Glenfield, Groby', 'One of UK''s most diverse cities, strong birth rates, established Oadby and Wigston suburbs, 500K+ metro area.', 'NCT Leicester, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5cvxl8625","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Leicester is one of the UK''s most diverse cities with a population exceeding 370,000 and a wider metro area beyond 500,000. Birth rates are consistently strong, driven by diverse communities where family is central to everything."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xyery8627","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"la3px8628","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Oadby and Wigston are established, affluent suburbs with engaged parents. Birstall and Glenfield attract young professional families. The city''s diverse communities bring volume and cultural richness."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kd5x08630","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y37wo8631","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Leicester. A wide range of independent baby classes operate from venues throughout the city and suburbs. The strong community infrastructure provides plenty of opportunities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hfc058633","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kvtv08634","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Leicester''s diversity, strong birth rates, and established family suburbs make it one of the most compelling territories in the East Midlands."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Leicester region covers Leicester city centre, Oadby, Wigston, Birstall, Glenfield, and Groby. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"4m94632278","nodes":[{"id":"w0tfj32279","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0kmr616510","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Leicester"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xejpz32281","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"71jfs16512","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ao67332283","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6ikth16514","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ojuas32285","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3n0bd16516","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"q1o5s32287","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"djme216518","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Leicester''s parenting communities are diverse, warm, and deeply connected.', null, 'Baby Keepsake Franchise Opportunity in Leicester', 'Start a flexible Memory Catcher franchise in Leicester. Capture baby handprints and footprints across one of the UK''s most diverse cities with full training and support.', 52.64, -1.13, 500000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('edinburgh', 'Edinburgh', 'Edinburgh', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Scotland''s capital, where affluence meets a deeply rooted family culture.', 'Edinburgh city centre, Morningside, Stockbridge, Leith, Corstorphine, surrounding suburbs', 'Scotland''s capital, highly educated and affluent demographic, premium pricing potential, compact city with strong baby class infrastructure.', 'NCT Edinburgh, Bump and Baby Club Morningside, multiple independent baby class providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yg58r457","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Edinburgh is Scotland''s flagship Memory Catcher territory, and for good reason. With a population of over 530,000 and one of the most highly educated demographics in the UK, the capital attracts professionals who settle into family life across its desirable neighbourhoods. Areas like Morningside, Stockbridge, and Corstorphine are magnets for young families drawn by excellent schools, green spaces, and a quality of life that''s hard to match anywhere else in Scotland."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iinjb60028","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qrl7m459","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What sets Edinburgh apart is the willingness of its parents to invest in premium products and experiences. This is a city where artisan markets thrive, where independent businesses are championed over chains, and where parents actively seek out meaningful, handcrafted keepsakes. The Memory Catcher service fits the Edinburgh parent perfectly, something beautiful, personal, and made with real craftsmanship."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gasu660034","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2hrqn461","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The baby class scene in Edinburgh is well established. NCT runs popular antenatal courses and postnatal meetups across the city, and the Bump and Baby Club operates out of Morningside. A wide range of independent baby sensory, massage, and development classes run weekly across Edinburgh''s community centres, church halls, and private venues. The city is compact enough that a single franchisee can cover multiple sessions per day without long commutes between venues."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v0sa660040","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"29nz3463","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"As Scotland''s capital territory, the Edinburgh Memory Catcher carries a particular prestige. This is the anchor for the Scottish network, and it offers something most regions outside London can''t match: genuine premium pricing potential combined with strong community infrastructure. Edinburgh parents pay for quality, and they recommend it to their friends."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Edinburgh region covers Edinburgh city centre, Morningside, Stockbridge, Leith, Corstorphine, and the surrounding suburbs. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"o6mmg24491","nodes":[{"id":"bmqsx24492","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4jtfx10238","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Edinburgh antenatal and postnatal groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"1xfo424494","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f4hy710240","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bump and Baby Club Morningside"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9oukz24496","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"71ypl10242","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7m66024498","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ys99h10244","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs across Edinburgh"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"864qg24500","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"d0m5o10246","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Edinburgh''s parenting community is well connected and recommendation-driven. NCT groups here form strong social bonds, and class leaders are trusted voices in the local family network. Being introduced through those established communities gives you a warm start from day one.', null, 'Baby Keepsake Franchise in Edinburgh, Capital Region', 'Start a flexible Memory Catcher franchise in Edinburgh. Capture baby handprints and footprints across Scotland''s capital with full training, support, and a protected region.', 55.95, -3.19, 530000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('south-wales-valleys', 'Valleys', 'South Wales Valleys', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the South Wales Valleys'' tight-knit communities.', 'Merthyr Tydfil, Pontypridd, Caerphilly, Aberdare, Blackwood, Ebbw Vale', '450K+ combined, legendary community spirit, fierce loyalty, tight-knit valley communities, accessible pricing.', 'NCT South Wales, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sd3hn11392","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The South Wales Valleys have a combined population exceeding 450,000 spread across some of the most tight-knit communities in the UK. The A470 corridor connects valley towns united by fierce community identity."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mz3ps11394","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"swtyq11395","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Everyone knows everyone in the valleys. When a family finds something they love, they tell their family, friends, neighbours, and baby class group. That organic word of mouth is more powerful than any marketing campaign."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight"