insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bradford', 'Bradford', 'Bradford', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the UK''s youngest and most diverse cities.', 'Bradford city centre, Shipley, Saltaire, Ilkley, Bingley, Baildon', 'One of UK''s youngest cities, highest birth rates, Ilkley premium pocket, 540K+ population, diverse multicultural market.', 'NCT Bradford, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"n6wgs7768","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bradford is one of the youngest cities in the UK with one of the highest birth rates of any major city in England. The metropolitan district has a population exceeding 540,000, providing genuine scale."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l4d567770","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4cvw07771","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Ilkley, at the northern edge, is one of Yorkshire''s most affluent towns with premium pricing potential. Saltaire and Shipley attract creative families. The broader Bradford community adds volume through its young, diverse population where family keepsakes hold deep cultural significance."},"type":"TEXT"}],"type":"PARAGRAPH"},{"p