dingTop":"0px"},"id":"js95f13498","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vbi8u13499","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups in Cumbria. Independent baby classes operate from community centres across the main towns. Geographic spread means each area has its own distinct community."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6xp2z13501","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hiy2q13502","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cumbria requires an entrepreneurial mindset and willingness to travel. The reward is a self-contained market with virtually no competition and fiercely loyal communities."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Cumbria region covers Carlisle, Penrith, Workington, Kendal, Whitehaven, and Barrow-in-Furness. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"nj2ez37978","nodes":[{"id":"a481o37979","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ktgs421244","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Cumbria"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5fyer37981","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ahax621246","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"