insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('cardiff', 'Cardiff', 'Cardiff and Vale of Glamorgan', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Welsh capital and its surrounding family communities.', 'Cardiff city centre, Pontcanna, Penarth, Barry, Cowbridge, Llandaff', 'Welsh capital, Pontcanna ''Nappy Valley'', Penarth premium coast, youngest city in Wales, Welsh network anchor.', 'NCT Cardiff, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vygpj11144","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Cardiff is the Welsh capital with a population exceeding 360,000. It has the youngest age profile of any Welsh city. Pontcanna is Cardiff''s ''Nappy Valley''. Penarth adds a premium coastal gem."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9qof511146","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j86zg11147","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Pontcanna has earned its reputation as Cardiff''s Nappy Valley, packed with cafes and baby classes. Penarth''s Victorian seaside charm and strong community make it another family favourite. Barry and Cowbridge extend the territory."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8h7kn11149","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e353f11150","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across Cardiff and the Vale. Independent baby classes operate throughout. Pontcanna and Penarth have particularly vibrant baby class scenes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zh1rl11152","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"haajy11153","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"As the anchor territory for the Welsh network, Cardiff offers the strongest combination of volume, premium pockets, and community infrastructure of any Welsh territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Cardiff and Vale of Glamorgan region covers Cardiff city centre, Pontcanna, Penarth, Barry, Cowbridge, and Llandaff. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"xufcm35319","nodes":[{"id":"63zyx35320","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8lepu18973","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Cardiff and Vale of Glamorgan"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9kd2a35322","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2ntud18975","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9qvqf35324","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l1gzj18977","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7587z35326","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7akmr18979","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"950kq35328","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"185wy18981","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Cardiff''s parenting communities are warm, diverse, and well-connected. Pontcanna''s reputation speaks for itself.', null, 'Baby Keepsake Franchise Opportunity in Cardiff', 'Start a flexible Memory Catcher franchise in Cardiff. Capture baby handprints and footprints across the Welsh capital with full training and support.', 51.48, -3.18, 500000)
