insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('nottingham', 'Nottingham', 'Nottingham', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the East Midlands'' youngest, most vibrant cities.', 'Nottingham city centre, West Bridgford, Beeston, Arnold, Carlton, Mapperley', 'One of UK''s youngest cities (median 31.3), West Bridgford premium suburb, university pipeline, East Midlands anchor territory.', 'NCT Nottingham, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3q7fr8501","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Nottingham is one of the youngest cities in the UK with a median age of just 31.3. Two universities feed a constant pipeline of young families. West Bridgford is the city''s premier family suburb."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dd22t8503","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sanza8504","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"West Bridgford is the jewel of this territory, one of the most desirable family areas in the East Midlands. Beeston, Mapperley, and Arnold add further depth. Parents across Nottingham value creativity, independence, and meaningful products."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textSty