ddingTop":"0px"},"id":"evfkw9703","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0zwq79704","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is very active across Surrey. Independent baby classes run throughout. The baby class scene is established, quality-focused, and consistently well-attended."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"50ry79706","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pb88k9707","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Surrey is a premium territory with exceptional per-session earning potential. Every session has the potential to generate above-average revenue."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Surrey region covers Guildford, Woking, Farnham, Godalming, Cranleigh, and Weybridge. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"ccskz33657","nodes":[{"id":"0w8cf33658","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"alo6g17488","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Surrey"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cmunk33660","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jbdpv17490","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9amps33662","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wi8cq17492","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Premium baby yoga and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"g80bc33664","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1ca6817494","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"d7pc133666","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rg49a17496","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Surrey''s parenting communities are well-connected and quality-driven. Strong NCT networks and engaged parent circles.', null, 'Baby Keepsake Franchise Opportunity in Guildford and Woking', 'Start a flexible Memory Catcher franchise across Surrey''s premium heartland. Capture baby handprints and footprints in one of England''s most affluent areas with full training and support.', 51.28, -0.575, 250000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('essex-north', 'North Essex', 'North Essex: Chelmsford and Colchester', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North Essex''s thriving family towns.', 'Chelmsford, Colchester, Braintree, Witham, Maldon, Brentwood', 'Chelmsford happiest place to live, Colchester England''s oldest town, London commuter premium, university and military pipeline.', 'NCT North Essex, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0b38s10657","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Chelmsford was voted the happiest place to live in Essex. Colchester, England''s oldest recorded town, offers heritage alongside a growing family population. The London commuter influence brings premium spending patterns."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u9hpt10659","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hv2i610660","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Chelmsford and Brentwood attract affluent commuters. Colchester''s university and garrison provide young family pipelines. Market towns add community warmth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gvb2910662","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lxdyn10663","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across the territory. Independent baby classes operate throughout. The baby class scene is well-established with a full weekly calendar."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e22ci10665","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yuj8f10666","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Essex offers a strong blend of premium markets and consistent volume. London commuter influence brings premium spending."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your North Essex region covers Chelmsford, Colchester, Braintree, Witham, Maldon, and Brentwood. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"mbg4a34688","nodes":[{"id":"dl6q034689","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j0rjq18498","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT North Essex"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"hhs4e34691","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ju1gl18500","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"sjax934693","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xbbla18502","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"0fqy334695","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mn50f18504","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"7debf34697","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"76mun18506","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'North Essex''s family communities are engaged and quality-conscious.', null, 'Baby Keepsake Franchise Opportunity in Chelmsford and Colchester', 'Start a flexible Memory Catcher franchise across North Essex. Capture baby handprints and footprints locally with full training and support.', 51.82, 0.68, 380000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('newcastle', 'Newcastle', 'Newcastle and Gateshead', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the North East''s vibrant capital.', 'Newcastle city centre, Jesmond, Gosforth, Gateshead, Low Fell, Whickham', 'North East''s capital, young demographics, premium Jesmond and Gosforth suburbs, legendary Geordie community spirit, compact city.', 'NCT Newcastle and Gateshead, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k8boj7144","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Newcastle is the cultural and economic heart of the North East, with a population exceeding 300,000 in the city proper and a further 200,000 across Gateshead. The city has one of the youngest demographics in the UK, driven by two major universities that retain graduates who go on to start families. Jesmond and Gosforth are the premier family suburbs, attracting young professionals putting down roots."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ewzmz7146","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cver77147","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Geordie warmth is real, and it translates directly into the kind of community connections that make a Memory Catcher thrive. Newcastle parents are engaged, social, and fiercely loyal to businesses they trust. The parenting culture here is vibrant, and Gateshead adds depth with established family areas in Low Fell and Whickham."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"am2qh7149","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cnpmg7150","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is well-established across Newcastle and Gateshead with regular antenatal and postnatal groups. A wide range of independent baby sensory, music, and development classes run from venues throughout the territory. The city''s compact geography means a franchisee can cover multiple sessions per day without excessive travel."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"q9du37152","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6ozp47153","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Newcastle is the anchor territory for the North East network. Its combination of young demographics, strong community spirit, and premium family suburbs in Jesmond and Gosforth make it one of the most compelling territories outside London and Manchester."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Newcastle and Gateshead region covers Newcastle city centre, Jesmond, Gosforth, Gateshead, Low Fell, and Whickham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"pcuc230466","nodes":[{"id":"3rf7b30467","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"o0jap15048","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Newcastle and Gateshead"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5xyjc30469","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j2hz915050","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"bo9gu30471","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"djmpj15052","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"uiqsu30473","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"elcx515054","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"uibcy30475","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"a912h15056","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Newcastle''s parenting community is warm, welcoming, and incredibly well-connected. The Geordie spirit of looking after your own extends right into the baby class world.', null, 'Baby Keepsake Franchise Opportunity in Newcastle and Gateshead', 'Start a flexible Memory Catcher franchise across Newcastle and Gateshead. Capture baby handprints and footprints in the North East''s vibrant capital with full training and support.', 54.97, -1.61, 500000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('birmingham', 'Birmingham', 'Birmingham Central and South', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the UK''s second city, where birth rates are rising faster than anywhere else in England.', 'Birmingham city centre, Edgbaston, Moseley, Kings Heath, Harborne, Selly Oak, Hall Green, Solihull', 'UK''s largest birth rate increase in 2024 (+1,323), median age 33.7, strong baby class infrastructure, premium pockets in Edgbaston, Moseley, and Solihull.', 'Baby Sensory Birmingham West, Bump and Baby Club Moseley, Birth and Baby Club, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hjivi1137","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Birmingham''s sheer scale sets it apart. With over 1.1 million residents in the city proper and a catchment that stretches into Solihull''s affluent suburbs, a Memory Catcher here has access to the largest addressable baby market outside London. The data doesn''t just support this region, it demands it be filled first."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zmwxq2184","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ansgi1186","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across South Birmingham are exactly where a Memory Catcher thrives. From the leafy streets of Moseley and Kings Heath, where independent coffee shops double as parenting hubs, to the professional families settling in Edgbaston and Harborne, this is a city full of parents who value quality, craftsmanship, and meaningful keepsakes. Solihull to the south adds a premium pocket where average order values run higher."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5ue252193","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yz66r1209","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The baby class scene in Birmingham is well established and growing. Baby Sensory runs classes across West Birmingham, the Bump and Baby Club operates popular antenatal sessions in Moseley, and the Birth and Baby Club covers the wider area with both in-person and online classes. NCT groups are active across the city and multiple independent sensory, massage, and development classes run weekly from community centres, church halls, and family hubs throughout the region."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5zroa2205","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cksqb1232","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Birmingham''s sheer scale sets it apart. With over 1.1 million residents in the city proper and a catchment that stretches into Solihull''s affluent suburbs, a Memory Catcher here has access to the largest addressable baby market outside London. The data doesn''t just support this region, it demands it be filled first."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Birmingham Central and South region covers Birmingham city centre, Edgbaston, Moseley, Kings Heath, Harborne, Selly Oak, Hall Green, and parts of Solihull. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"gus1223701","nodes":[{"id":"sscj323702","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sz31z9615","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby Sensory Birmingham West"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"u9qzl23704","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ynlxg9617","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bump and Baby Club Moseley"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"94rqm23706","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f7ecv9619","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Birth and Baby Club Birmingham"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"dp0xf23708","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qz3zz9621","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Birmingham and Solihull"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"d0vem23710","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3xczu9623","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Multiple independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"8l98p23712","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x6b6v9625","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Birmingham''s baby class network is thriving and well connected. Class leaders across the city already know the value of partnering with trusted local businesses, and the community infrastructure here means you won''t be starting cold. You''ll be stepping into a city that''s ready for a Memory Catcher.', '3443c751-1265-4d61-be0b-c81903ee9c20', 'Baby Keepsake Franchise Opportunity in Birmingham', 'Start a flexible Memory Catcher franchise in Birmingham, the UK''s fastest-growing baby market. Capture handprints and footprints locally with full training, support, and a protected region.', 52.45, -1.9, 600000)
