agraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"awkk711645","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland runs groups across the area. Independent baby classes operate throughout. Well-connected transport links keep the territory manageable."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cvhoc11647","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3a2ud11648","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Greater Glasgow is a volume territory with genuine scale. The 700,000+ population provides an enormous potential customer base."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Greater Glasgow region covers East Kilbride, Hamilton, Motherwell, Paisley, Cumbernauld, and Coatbridge. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"dhxkh35895","nodes":[{"id":"r5o5535896","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"csfjo19527","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland Greater Glasgow"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"jrqum35898","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cneza19529","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"btlsn35900","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO