insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('fife', 'Fife', 'Fife', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Kingdom of Fife''s family communities.', 'Kirkcaldy, Dunfermline, Glenrothes, St Andrews, Cupar', '370K+ Kingdom of Fife, St Andrews premium market, fast-growing Dunfermline, strong distinct Scottish identity, established family infrastructure.', 'NCT Fife, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s593f6430","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Fife has a population exceeding 370,000, making it one of the largest local authority areas in Scotland. The ''Kingdom'' has a strong, distinct identity separate from Edinburgh and Glasgow, and its family communities are proud and deeply rooted. Dunfermline is one of Scotland''s fastest-growing towns, St Andrews offers world-renowned prestige, and Kirkcaldy and Glenrothes provide family volume across the central belt."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"k92ie6432","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tgr6p6433","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"St Andrews adds a unique premium dimension to this territory. The university town''s international character and affluent demographics create a pocket where average order values run high. Dunfermline''s explosive growth brings a constant stream of new families, and the established towns across Fife provide consistent community warmth and demand."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sghvh6435","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hxfwo6436","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Fife runs groups across the area, and independent baby classes operate from venues throughout the territory. The growing Dunfermline area has seen rapid expansion of baby class provision. Community centres, church halls, and family hubs provide regular sessions across Fife''s main towns."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"08vl86438","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4rqey6439","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Fife offers the scale and community pride of a standalone territory with genuine premium potential through St Andrews. Dunfermline''s growth keeps the market expanding, and the Kingdom''s distinct identity means a local Memory Catcher will connect deeply with families who are proud to call Fife home."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Fife region covers Kirkcaldy, Dunfermline, Glenrothes, St Andrews, and Cupar. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"afmyl29585","nodes":[{"id":"yqr3529586","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"acekj14313","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Fife"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"fhlmq29588","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c7w7f14315","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"isg6r29590","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xu77o14317","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"udjgf29592","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"59vlb14319","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"hyp6z29594","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2kafv14321","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Fife''s communities are proud and well-connected. The Kingdom''s distinct identity creates natural community bonds, and families here support local businesses with genuine loyalty.', null, 'Baby Keepsake Franchise Opportunity in Fife', 'Start a flexible Memory Catcher franchise across the Kingdom of Fife. Capture baby handprints and footprints locally with full training, support, and a protected region.', 56.2, -3.15, 370000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('kent-north', 'North Kent', 'North Kent: Dartford, Gravesend and Medway', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North Kent''s growing family corridor.', 'Dartford, Gravesend, Rochester, Chatham, Gillingham, Strood', 'Kent +362 births in 2024, Thames Gateway growth corridor, 450K+ population, London family influx.', 'NCT North Kent, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kqrrw9461","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Kent is one of the fastest-growing areas in the South East. Kent recorded 362 more births in 2024. Dartford and Gravesend attract young families from London. The combined territory exceeds 450,000 residents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f8k8e9463","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cr2en9464","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"New developments across the Thames Gateway are bringing young professional families. Established communities in Rochester and Chatham provide depth. Parents here are community-minded and keen to connect."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e0gby9466","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rrrpz9467","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the area. The growing population has spurred expansion of baby class providers. Community centres and family hubs provide further opportunities."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p90if9469","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"57qbh9470","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"North Kent''s growth trajectory makes this territory stand out. The continuous influx of young families means the market is expanding year on year."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your North Kent region covers Dartford, Gravesend, Rochester, Chatham, Gillingham, and Strood. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"piwq933250","nodes":[{"id":"6n8on33251","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ftca117249","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT North Kent"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"j4si933253","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vo6gx17251","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"g6kyy33255","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b50mj17253","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"2ua9h33257","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"penmk17255","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"cg1q933259","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1z2ae17257","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'North Kent''s growing family communities are eager to connect and build networks.', null, 'Baby Keepsake Franchise Opportunity in North Kent', 'Start a flexible Memory Catcher franchise across North Kent''s growing family corridor. Capture baby handprints and footprints locally with full training and support.', 51.42, 0.45, 450000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('greenwich-lewisham', 'Greenwich and Lewisham', 'London: Greenwich and Lewisham', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across South East London''s growing family boroughs.', 'Greenwich, Lewisham, Blackheath, Lee, Eltham, Catford, Forest Hill', 'Growing South East London family area, Blackheath premium pocket, Greenwich regeneration attracting young families, underserved market with strong potential.', 'NCT Greenwich and Lewisham, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u1ums1662","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Greenwich and Lewisham sit at the heart of South East London''s family belt. The regeneration around Greenwich Peninsula and Woolwich has brought thousands of young professionals into new-build developments, while established areas like Blackheath, Lee, and Forest Hill continue to attract families who want the best of both worlds, green spaces and village feels within easy reach of central London. Together these boroughs have a combined population exceeding 580,000."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sz2z41664","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zmhu51665","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Blackheath is the jewel of this territory, a genuinely premium pocket where affluent families gather around the heath, attend the independent shops of Tranquil Vale, and invest in quality products and experiences for their children. Forest Hill and Catford are emerging family areas where younger parents are settling, creating vibrant new parenting communities. The mix of established affluence and emerging energy gives this territory real depth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lmf0e1667","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u7hg11668","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT is active across both boroughs with regular antenatal and postnatal groups. Independent baby classes run from venues throughout the territory, with Blackheath and Forest Hill particularly well-served. Children''s centres, family hubs, and community venues provide additional touchpoints for connecting with new parents across the area."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"61acg1670","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"s4zej1671","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"South East London has long been underserved compared to the south west, which means there''s genuine room for a Memory Catcher to establish themselves as the go-to keepsake service in the area. The combination of Blackheath''s premium demographics and the growing family populations across Greenwich and Lewisham creates a territory with strong, balanced potential."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Greenwich and Lewisham region covers Greenwich, Lewisham, Blackheath, Lee, Eltham, Catford, and Forest Hill. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"fbk2o25794","nodes":[{"id":"tifeb25795","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"moows11350","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Greenwich and Lewisham"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kry8825797","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0khtg11352","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"k1znq25799","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"f0obz11354","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"438to25801","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mvc2611356","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"uqata25803","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ffx1111358","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups and family centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'South East London''s family communities are warm and well-connected, with Blackheath acting as a natural hub for parents across the wider area. The community spirit here is strong, and local businesses earn loyalty through genuine relationships.', null, 'Baby Keepsake Franchise Opportunity in Greenwich and Lewisham', 'Start a flexible Memory Catcher franchise across Greenwich and Lewisham. Capture baby handprints and footprints in South East London with full training, support, and a protected region.', 51.46, 0.01, 590000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bury-rossendale', 'Bury and Rossendale', 'Bury and Rossendale', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across north Greater Manchester''s community-rich towns.', 'Bury, Ramsbottom, Tottington, Prestwich, Whitefield, Rawtenstall', 'Ramsbottom premium family area, Prestwich creative community, existing baby class partnerships, flexible full-time or part-time potential.', 'Established baby class partners, NCT groups, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6rs4h3409","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bury and Rossendale offer a distinctive mix of characterful market towns and growing suburban communities just north of Manchester. Ramsbottom has become one of the most sought-after family destinations in the region, known for its independent shops, award-winning restaurants, and vibrant community. Prestwich has emerged as a hotspot for creative young families priced out of Chorlton and Didsbury, bringing fresh energy to the area."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fa0kh3411","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eyb033412","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities here are genuine and welcoming. From Ramsbottom''s artisan culture to Prestwich''s creative parent community and Bury''s traditional family values, parents across this territory are engaged and community-minded. These are parents who value handcrafted, meaningful products and who build lasting relationships with local businesses they believe in."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qf8mk3414","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"okpyn3415","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, providing existing connections. NCT groups are active across the territory, and independent baby classes run from venues throughout Bury, Prestwich, and the surrounding towns. The community infrastructure is well-developed and growing alongside the area''s population."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8wvyw3417","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"8xa3s3418","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory works well as either a full-time or part-time franchise. The Ramsbottom and Prestwich premium pockets drive strong average order values, while the broader Bury area provides consistent volume. The existing baby class partnership gives you a warm start from day one."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bury and Rossendale region covers Bury, Ramsbottom, Tottington, Prestwich, Whitefield, and Rawtenstall. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"e5d2228245","nodes":[{"id":"xedot28246","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y9ipt13190","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"i5ily28248","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zz3ni13192","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Bury"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9vjwi28250","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"by5j613194","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"nghca28252","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ysutm13196","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"x6qqh28254","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h51dh13198","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across Bury and Rossendale are warm, creative, and deeply connected. Ramsbottom in particular has a thriving independent culture where local businesses are championed and supported passionately.', null, 'Baby Keepsake Franchise Opportunity in Bury and Rossendale', 'Start a flexible Memory Catcher franchise across Bury and Rossendale. Capture baby handprints and footprints locally with full training, support, and a protected region.', 53.64, -2.3, 260000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('leeds', 'Leeds', 'Leeds', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the North''s most family-friendly cities, with warm Established baby class partners', 'Leeds city centre, Headingley, Chapel Allerton, Roundhay, Horsforth, Meanwood', 'UK''s 4th largest city, existing Established baby class partners, affluent northern suburbs, strong community culture.', 'Established baby class partners, Established baby class partners, NCT groups, Little Seedlings, multiple independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"23r9t709","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Leeds is the fourth largest city in the UK with a population exceeding 536,000, and its northern suburbs are some of the most desirable family areas in the country. Roundhay, Horsforth, Chapel Allerton, and Headingley attract young professionals and growing families drawn by excellent schools, green spaces, and a thriving independent scene. These are parents who invest in quality experiences for their children and value meaningful, handcrafted keepsakes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"515we60338","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kaq65711","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes Leeds particularly exciting for a Memory Catcher is the existing Established baby class partners, Wetherby, and Leeds West from venues in Alwoodley, Wetherby, Chapel Allerton, Pudsey, and Horsforth, with classes regularly selling out. These are existing warm connections for The Bespoke Foil Company, which means you''re not building relationships from scratch, you''re stepping into established, trusted communities where the introductions have already been made."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7ya8d60349","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cmq8p713","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Beyond these partnerships, the baby class scene in Leeds is thriving. Little Seedlings runs popular sessions in Chapel Allerton, NCT groups are active across the city, and a wide range of independent baby sensory, massage, and development classes operate weekly. Happity lists dozens of baby and toddler classes across North Leeds alone. The infrastructure is there, the parents are there, and the community connections are ready and waiting."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xayw060359","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gg0yw715","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Leeds offers a rare combination: a large city with proven baby class partnerships, affluent family suburbs that drive above-average order values, and a community culture where trust and word-of-mouth recommendations are everything. For a Memory Catcher ready to hit the ground running, there are few better places to start."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Leeds region covers Leeds city centre, Headingley, Chapel Allerton, Roundhay, Horsforth, and Meanwood. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"bk65924774","nodes":[{"id":"1t2ap24775","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"a1ljy10472","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, Wetherby, Chapel Allerton)"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"oabb424777","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"b8l0210474","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, Horsforth)"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"z3wtv24779","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"q7ari10476","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Little Seedlings Chapel Allerton"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rpexm24781","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dpl8910478","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Leeds"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"l9wcf24783","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"23rfr10480","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Multiple independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"gzf4a24785","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zrusm10482","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'This is one of the warmest territories in the network. Local baby class leaders already know and trust The Bespoke Foil Company, and their classes are packed with exactly the parents a Memory Catcher needs to meet. You''ll be walking into rooms where the ground has already been laid.', null, 'Baby Keepsake Franchise in Leeds, West Yorkshire UK', 'Start a flexible Memory Catcher franchise in Leeds with warm Established baby class partners', 53.8, -1.55, 800000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('manchester', 'Manchester', 'Manchester Central', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of the UK''s youngest, most vibrant cities.', 'Manchester city centre, Salford, Stretford, Didsbury, Chorlton, Withington', 'Youngest major city demographic in the UK, strong Established baby class partners, creative and professional young families.', 'Multiple Established baby class partners, NCT groups, and independent providers', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jx20m340","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Manchester is one of the best places in the UK to be a Memory Catcher, and the data backs it up. With a median age of just 30.4, it''s the youngest major city in the country. That means a constant stream of new parents, new babies, and new families looking for meaningful ways to capture those early moments before they slip away."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yxi3d342","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eojum343","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"From the young professionals settling in Didsbury and Chorlton to the growing families across Salford, Stretford, and Withington, Manchester is full of parents who care deeply about preserving memories but are too busy juggling everything else to make it happen on their own. That''s exactly where you come in."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"spxia345","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3gvem346","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The baby class scene here is thriving. Established baby class partners, including Worsley, Pendlebury, Prestwich, Cadishead, and Salford, as well as Trafford and Eccles. NCT groups are active across the city. These aren''t just classes, they''re communities of parents who meet week after week, building trust and relationships. As a Memory Catcher, you step into that warmth from day one."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g3uk2348","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j9e2c349","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"And because our founder Ashley is based nearby, Manchester franchisees get something no other region can offer - direct, in-person support during your early months. She knows these communities, she''s worked these classes, and she''ll be there to help you find your feet."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Manchester Central region covers Manchester city centre, Salford, Stretford, Didsbury, Chorlton, and Withington. This is your exclusive area - no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"tx59u24352","nodes":[{"id":"qjxcu24353","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tc6r910109","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners, Pendlebury, Prestwich, Cadishead, Salford)"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kk3hs24355","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kpqu510111","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Established baby class partners"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5lakw24357","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"q7nmv10113","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT groups across Manchester and Salford"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4c0f324359","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2x5lw10115","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Multiple independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"yd63g24361","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"grf7810117","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres, church halls, and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'These aren''t cold leads. Our baby class partners reach thousands of parents every week across the UK, and their Manchester franchisees already know and trust The Bespoke Foil Company. You won''t be starting from scratch - you''ll be stepping into warm, established communities where the introductions have already been made.', null, 'Baby Keepsake Franchise Opportunity, Manchester UK', 'Start a flexible Memory Catcher franchise in Manchester, capturing baby handprints and footprints locally, with full training, support, and protected region.', 53.48, -2.245, 560000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('edinburgh-lothians', 'Lothians', 'Edinburgh Greater Lothians', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Edinburgh''s commuter belt and family suburbs.', 'Livingston, Musselburgh, Dalkeith, Bathgate, Penicuik, Dunbar', '350K+ Edinburgh commuter belt, fast-growing Livingston, young family demographics, affordable Scottish network entry.', 'NCT Scotland, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p3bwk11754","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Lothians surrounding Edinburgh have a combined population exceeding 350,000. Livingston is one of Scotland''s fastest-growing towns. Musselburgh and Dalkeith offer affordable family living."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jylb111756","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"t132711757","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Young professional families are drawn by affordable housing, good schools, and easy Edinburgh commutes. These parents are actively seeking community connections."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v3u7g11759","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ycrtd11760","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland runs groups across the Lothians. Independent baby classes operate throughout. The growing population means new classes opening regularly."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e37ns11762","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3wtkf11763","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Lothians offer strong volume alongside Edinburgh''s premium anchor territory. Growing family communities with consistent demand."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Edinburgh Greater Lothians region covers Livingston, Musselburgh, Dalkeith, Bathgate, Penicuik, and Dunbar. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"r1hks36035","nodes":[{"id":"xnkd236036","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7z2s719666","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Scotland Lothians"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"mloi336038","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"21cuj19668","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"zshdo36040","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g3aos19670","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kj76536042","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ukiqc19672","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"97fio36044","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jewm319674","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The Lothians'' family communities are growing and eager to connect.', null, 'Baby Keepsake Franchise Opportunity in the Lothians', 'Start a flexible Memory Catcher franchise across Edinburgh''s Lothians. Capture baby handprints and footprints locally with full training and support.', 55.88, -2.95, 350000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('lambeth-southwark', 'Lambeth and Southwark', 'London: Lambeth and Southwark', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across South London''s diverse, vibrant boroughs.', 'Lambeth, Southwark, Brixton, Dulwich, Peckham, Herne Hill, Camberwell', 'Diverse South London boroughs, Dulwich ultra-premium pocket, thriving Herne Hill family hub, strong baby class scene, 650K+ combined population.', 'NCT Lambeth and Southwark, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"18xu91909","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Lambeth and Southwark are two of South London''s most dynamic boroughs, home to a diverse mix of young professionals, creative communities, and established families. Dulwich Village is one of London''s premier family destinations with a distinctly premium feel, while Herne Hill, Brixton, and Peckham have transformed into thriving family areas where independent culture and community spirit run deep. Together, these boroughs have a combined population exceeding 650,000."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ucejj1911","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p97j51912","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The parenting culture across these boroughs reflects their character, engaged, diverse, and community-driven. From the polished NCT circuit in Dulwich to the colourful parent meetups in Brixton and Peckham, parents here are actively involved in their local communities and value products and services that feel personal and meaningful. Herne Hill has emerged as a particular family hotspot, with its weekend market, independent cafes, and packed baby class timetable."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rsgh81914","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"bpewj1915","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Lambeth and Southwark are thriving. NCT runs well-attended groups across both boroughs, and a wide variety of independent baby sensory, music, yoga, and development classes run from venues throughout the territory. Dulwich, Herne Hill, and East Dulwich are particularly well-served, with multiple sessions running every day of the week."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6k06n1917","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"p1vcm1918","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This territory offers exceptional variety. The ultra-premium pocket of Dulwich Village drives above-average order values, while the broader territory across Brixton, Peckham, and Camberwell provides volume and diversity. For a Memory Catcher who can read different communities and adapt their approach, this is one of the most rewarding territories in the network."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Lambeth and Southwark region covers Lambeth, Southwark, Brixton, Dulwich, Peckham, Herne Hill, and Camberwell. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"v97gc26068","nodes":[{"id":"7b29h26069","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"no8mf11589","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Lambeth and Southwark"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"8m7wa26071","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pqdle11591","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"v6tp526073","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"l4f2b11593","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby yoga and massage classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"bip3826075","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7fmul11595","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"uer9j26077","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0fsl111597","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'South London''s parenting communities are diverse, creative, and fiercely local. From Dulwich''s polished parent networks to Brixton''s vibrant family scene, once you''re known and trusted in these communities, the support and referrals are genuine and lasting.', null, 'Baby Keepsake Franchise Opportunity in Lambeth and Southwark', 'Start a flexible Memory Catcher franchise across Lambeth and Southwark. Capture baby handprints and footprints in South London with full training, support, and a protected region.', 51.47, -0.1, 640000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('barnet-enfield', 'Barnet and Enfield', 'London: Barnet and Enfield', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across North London''s largest family boroughs.', 'Barnet, Enfield, Finchley, Whetstone, Southgate, Winchmore Hill, Palmers Green', 'London''s most populous borough (Barnet 400K+), strong suburban family communities, high birth volumes, established baby class infrastructure.', 'NCT Barnet and Enfield, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v15101427","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Barnet is the most populous borough in London with over 400,000 residents, and Enfield adds a further 330,000, making this one of the largest territories in the network by population. These outer North London boroughs are defined by their suburban character, with tree-lined streets, good schools, and strong family communities that attract young professionals looking for more space without leaving the capital."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g4gxi1429","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fwyd91430","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across Finchley, Whetstone, Southgate, and Winchmore Hill are well-established and growing. These are neighbourhoods where parents invest in their children''s experiences, attend classes regularly, and form lasting friendships through the baby class circuit. The suburban feel creates a sense of community that''s often missing in inner London, and that community warmth is exactly what makes a Memory Catcher territory thrive."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"id7zf1432","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vscrj1433","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs active groups across both boroughs, and a range of independent baby sensory, music, and development classes operate weekly from venues throughout the territory. Family centres and children''s centres across Barnet and Enfield provide additional touchpoints for connecting with new parents. The territory''s size means there''s no shortage of venues and classes to attend."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"jkpmh1435","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"nfwxw1436","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The sheer population scale of this territory sets it apart. With over 730,000 residents across two boroughs, the volume of new babies each year provides a consistent stream of potential customers. While pricing sits slightly below the ultra-premium inner London territories, the volume more than compensates, making this a high-earning territory for a committed Memory Catcher."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Barnet and Enfield region covers Barnet, Enfield, Finchley, Whetstone, Southgate, Winchmore Hill, and Palmers Green. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"lomdi25516","nodes":[{"id":"haeo225517","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xrny311091","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Barnet and Enfield"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"gc2qb25519","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cx81o11093","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9zzjq25521","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"4lv5911095","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family centres and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"rh6ud25523","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ppkw311097","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"80zfi25525","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6gh0911099","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The parenting communities across outer North London are warm and well-connected. The suburban character of these boroughs means parents see the same faces week after week at classes, building the kind of trust and familiarity that drives repeat business.', null, 'Baby Keepsake Franchise Opportunity in Barnet and Enfield', 'Start a flexible Memory Catcher franchise across Barnet and Enfield in North London. Capture baby handprints and footprints locally with full training, support, and a protected region.', 51.62, -0.175, 720000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('aberdeen', 'Aberdeen', 'Aberdeen and Aberdeenshire', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Scotland''s Granite City and its surrounding communities.', 'Aberdeen city centre, Westhill, Stonehaven, Inverurie, Ellon, Peterhead', 'Energy industry wealth, international family community, 490K+ combined population, self-contained market, keepsakes valued by relocated families.', 'NCT Aberdeen, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0x8tg6176","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Aberdeen has a population exceeding 230,000 in the city proper, with the wider Aberdeenshire adding a further 260,000+. The energy industry has created a wealthy city with high household incomes and a diverse, international population. Many families in Aberdeen have relocated from across the UK and beyond, meaning they often lack extended family support and particularly value capturing their children''s early milestones."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rzucr6178","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wosxw6179","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across Aberdeen and Aberdeenshire are engaged and well-connected. Westhill, Inverurie, and Stonehaven are popular family towns with strong local identities and affluent demographics. The international dimension of Aberdeen''s population adds cultural richness, with families from around the world bringing their own deep appreciation for family keepsakes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"zoyub6181","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pc7eb6182","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Aberdeen, and independent baby classes operate from venues throughout the territory. The city''s baby class scene is well-established, and the commuter towns add further opportunities. Community centres, church halls, and family hubs provide regular sessions across the area."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"etyv16184","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vyshp6185","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Aberdeen''s geographic isolation creates a self-contained market where a local Memory Catcher becomes the natural choice. The energy industry wealth, international family community, and lack of extended family support for many residents make this a territory where the Memory Catcher service is particularly valued."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Aberdeen and Aberdeenshire region covers Aberdeen city centre, Westhill, Stonehaven, Inverurie, Ellon, and Peterhead. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"3j5p829287","nodes":[{"id":"ve1l229288","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"849sh14057","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Aberdeen"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"9grr529290","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5z5p214059","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"neclp29292","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"uyu0r14061","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4ken429294","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"eth0914063","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qpdo229296","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wzkxf14065","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Aberdeen''s family communities are diverse, international, and well-connected. The energy industry culture of hospitality and celebration translates into a market that values meaningful keepsakes deeply.', null, 'Baby Keepsake Franchise Opportunity in Aberdeen', 'Start a flexible Memory Catcher franchise across Aberdeen and Aberdeenshire. Capture baby handprints and footprints in Scotland''s Granite City with full training, support, and a protected region.', 57.15, -2.15, 490000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('isle-of-wight', 'Isle of Wight', 'Isle of Wight', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Isle of Wight''s close-knit island community.', 'Newport IOW, Ryde, Cowes, Sandown, Shanklin, Ventnor', 'Self-contained island market, zero competition, close-knit community, boutique territory, lowest buy-in.', 'Independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"dcu9b14453","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Isle of Wight has a population of around 140,000 with a distinct island identity and close-knit communities. The island''s geographic isolation creates a self-contained market."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"wbn7b14455","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"ual2t14456","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Island communities are exceptionally close-knit. When a family loves a product or service, the entire island finds out. That organic word of mouth is unmatched."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v0g4514458","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fjxx414459","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes operate from community centres and family hubs across the island''s main towns."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j0kq414461","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tghga14462","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Isle of Wight is a boutique territory, smaller in population but self-contained with zero competition. Works well as part-time or combined with a coastal Hampshire territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Isle of Wight region covers Newport, Ryde, Cowes, Sandown, Shanklin, and Ventnor. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"pcfs056016","nodes":[{"id":"cagpb56017","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0x3di55955","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"e5zzd56019","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"h8lbc55960","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"s173y56021","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vxjj555965","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qelpa56023","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9zzov55970","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Island communities are close-knit and fiercely loyal.', null, 'Baby Keepsake Franchise Opportunity on the Isle of Wight', 'Start a flexible Memory Catcher franchise on the Isle of Wight. Capture baby handprints and footprints across this unique island community with full training and support.', 50.68, -1.3, 140000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('havering-barking', 'Havering and Barking', 'London: Havering and Barking', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across outer East London''s growing family communities.', 'Romford, Hornchurch, Upminster, Barking, Dagenham, Rainham', 'One of London''s highest birth rate areas, young diverse population in Barking, established Havering suburban families, strong volume territory.', 'NCT Havering and Barking, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"puzmv2532","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Havering and Barking & Dagenham represent outer East London''s family heartland. Barking & Dagenham has one of the youngest populations of any London borough and consistently records some of the highest birth rates in the capital. Havering adds a more suburban, established family community through Romford, Hornchurch, and Upminster, where families have been putting down roots for generations."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6v3ni2534","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"c8ptu2535","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"What makes this territory work is the volume. The birth rates across these boroughs are among the highest in London, driven by Barking & Dagenham''s young, diverse population and the steady flow of families moving to Havering for more space and better schools. Parents here value quality products for their children and form strong community bonds through baby classes and local groups."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lq0on2537","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"17cyp2538","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across the territory are growing. NCT runs groups in the area, and independent baby sensory, music, and development classes operate from community centres, church halls, and family hubs. Children''s centres across both boroughs provide additional opportunities for connecting with new parents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fx51a2540","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xa4252541","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"This is a volume territory. The consistently high birth rates, combined with the territory''s accessible buy-in price, make it an attractive option for a Memory Catcher who wants to build a full client base quickly. The community infrastructure is there, the parents are there, and the demand is consistent."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Havering and Barking region covers Romford, Hornchurch, Upminster, Barking, Dagenham, and Rainham. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6f7s126879","nodes":[{"id":"pdrg926880","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1sjbm12231","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Havering and Barking"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"3e6xj26882","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"mv3l412233","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"8vl8p26884","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"66e1112235","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Children''s centres and family hubs"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"a7m3j26886","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9usgx12237","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"xzw2h26888","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xy6my12239","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The family communities across outer East London are warm and grounded. Parents here support local businesses and build lasting relationships through baby classes and community groups. The strong sense of local identity works in a Memory Catcher''s favour.', null, 'Baby Keepsake Franchise Opportunity in Havering and Barking', 'Start a flexible Memory Catcher franchise across Havering and Barking. Capture baby handprints and footprints in outer East London with full training, support, and a protected region.', 51.55, 0.15, 480000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bath', 'Bath', 'Bath and North East Somerset', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across one of England''s most beautiful and affluent cities.', 'Bath, Keynsham, Midsomer Norton, Radstock, Frome', 'UNESCO World Heritage city, affluent quality-conscious families, creative Frome, boutique territory with premium average order values.', 'NCT Bath, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iyex810775","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bath is a UNESCO World Heritage Site. Its family demographics are defined by affluence and appreciation for heritage and craftsmanship. With Keynsham and Frome, the territory covers around 200,000 residents."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"gyr3710777","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"w8xzj10778","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bath parents are quality-conscious and community-engaged. Frome has become one of the most creative towns in the South West, attracting young families with its independent spirit."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"vea2f10780","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"49b9s10781","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across Bath. Independent baby classes operate throughout. Bath''s compact geography keeps venues accessible."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2pst510783","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"x9lqe10784","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bath is a boutique territory with premium potential. While smaller, the affluence and quality-consciousness mean strong average order values. Works as full-time or part-time."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bath region covers Bath, Keynsham, Midsomer Norton, Radstock, and Frome. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"elsnc34828","nodes":[{"id":"haa8k34829","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rk7zx18615","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Bath"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"kma4s34831","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lkxas18617","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"02bzl34833","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3p65018619","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"g88u734835","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"rsg5z18621","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ckd0z34837","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"0exd218623","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Bath''s parenting community is refined, engaged, and well-connected.', null, 'Baby Keepsake Franchise Opportunity in Bath', 'Start a flexible Memory Catcher franchise in Bath. Capture baby handprints and footprints across one of England''s most beautiful cities with full training and support.', 51.38, -2.36, 195000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('wirral', 'Wirral', 'Wirral', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Wirral Peninsula''s established family communities.', 'Birkenhead, Heswall, West Kirby, Bebington, Wallasey, Hoylake', 'Self-contained peninsula territory (320K+), affluent western coast, established family communities, compact geography, strong community identity.', 'NCT Wirral, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"2erc83039","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Wirral is a peninsula with a character all its own, distinct from Liverpool and Chester but connected to both. With a population exceeding 320,000, it offers a mix of affluent coastal communities in Heswall, West Kirby, and Hoylake, alongside established family areas in Bebington and the wider borough. The geography creates a natural, self-contained territory where a local Memory Catcher becomes the obvious choice."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3jr5f3041","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"r2nvu3042","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family communities across the Wirral are warm, loyal, and deeply rooted. Parents here tend to stay in the area, building lasting connections through schools, baby classes, and community groups. The affluent western coast in particular draws families who value quality and craftsmanship, making it a natural fit for handcrafted baby keepsakes."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"83d6z3044","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"hytzn3045","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the Wirral, and independent baby classes operate from venues throughout the peninsula. Church halls, community centres, and family hubs provide a steady calendar of sessions. The peninsula''s compact geography means travel between venues is manageable, and a Memory Catcher can attend multiple sessions across different areas in a single day."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3nc673047","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7zu5t3048","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The Wirral''s natural geographic boundary is its biggest advantage. The peninsula creates a self-contained market where a local franchisee can quickly become known and trusted across the entire community. The combination of affluent coastal pockets and established family areas creates a well-balanced territory."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Wirral region covers Birkenhead, Heswall, West Kirby, Bebington, Wallasey, and Hoylake. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"6e49w27446","nodes":[{"id":"t4oj327447","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"g01ha12708","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Wirral"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"il7k127449","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cgy4w12710","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pnx3927451","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"li1o012712","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"5foqj27453","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7o26y12714","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ldvej27455","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xvtbc12716","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'The Wirral''s community spirit is strong and genuine. The peninsula''s geography creates natural bonds between families, and word-of-mouth recommendations carry real weight in a community where everyone knows someone who knows someone.', null, 'Baby Keepsake Franchise Opportunity in Wirral', 'Start a flexible Memory Catcher franchise across the Wirral Peninsula. Capture baby handprints and footprints locally with full training, support, and a protected region.', 53.37, -3.08, 320000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('newport', 'Newport', 'Newport and Monmouthshire', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Newport and Monmouthshire''s growing family communities.', 'Newport, Cwmbran, Pontypool, Abergavenny, Chepstow, Monmouth', 'Highest fertility rate in Wales (1.64 TFR), Abergavenny premium rural market, growing Newport, balanced territory.', 'NCT Newport, independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"on3kv11518","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Newport has held the highest total fertility rate of any Welsh local authority since 2022 at 1.64. Monmouthshire adds a premium rural dimension through Abergavenny, Chepstow, and Monmouth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kunvl11520","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"olcjj11521","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Newport provides urban energy and volume. Monmouthshire''s families invest in premium products. Abergavenny''s food festival culture naturally embraces handcrafted products."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"6kzm711523","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e31h611524","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups in the area. Independent baby classes operate throughout. Community centres and family hubs provide regular sessions."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"3342511526","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"yk30i11527","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Newport''s record fertility rate combined with Monmouthshire''s premium market creates genuine balance. Works well as either full-time or part-time."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Newport and Monmouthshire region covers Newport, Cwmbran, Pontypool, Abergavenny, Chepstow, and Monmouth. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"2mgvu35750","nodes":[{"id":"8ihgv35751","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fi7fl19365","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Newport"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pzfwp35753","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5c7iu19367","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qme9u35755","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"j7blq19369","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ar6hk35757","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kkwcr19371","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"qhxwl35759","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1a3zw19373","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Newport and Monmouthshire''s communities offer the best of both worlds, urban diversity and rural warmth.', null, 'Baby Keepsake Franchise Opportunity in Newport and Monmouthshire', 'Start a flexible Memory Catcher franchise across Newport and Monmouthshire. Capture baby handprints and footprints locally with full training and support.', 51.65, -2.95, 250000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('bolton-wigan', 'Bolton and Wigan', 'Bolton and Wigan', false, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Greater Manchester''s proud, family-rich towns.', 'Bolton, Wigan, Horwich, Atherton, Leigh, Standish', 'Combined 470K+ population, strong Greater Manchester towns, fierce community loyalty, established family communities, excellent value territory.', 'NCT Bolton and Wigan, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"z1y163163","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bolton and Wigan are two of Greater Manchester''s most proudly independent towns, with a combined population exceeding 470,000. Both have strong family traditions and deeply rooted community identities that make them ideal Memory Catcher territory. These are communities where local businesses are supported passionately, where word of mouth carries genuine weight, and where families value authenticity above all else."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"tu5xq3165","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"sj69i3166","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"The family areas across both towns are well-established and growing. Horwich and Standish attract young professional families looking for more space and better value than central Manchester, while the wider communities across Bolton and Wigan provide consistent volume. Parents here care deeply about preserving family memories and they value products that are made with genuine care and craftsmanship."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"pubik3168","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"iribm3169","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Baby classes across Bolton and Wigan are well-attended. NCT runs groups in the area, and independent baby sensory, music, and development classes operate from community centres, church halls, and family hubs throughout both towns. The strong community infrastructure means there''s no shortage of warm rooms for a Memory Catcher to step into."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1tk0x3171","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"lwt7w3172","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Bolton and Wigan offer the warmth and community loyalty that''s essential for a Memory Catcher to thrive. The combined population provides strong volume, and the fierce local pride in both towns means that a franchisee from the area will connect with families on a genuine, personal level that drives lasting success."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Bolton and Wigan region covers Bolton, Wigan, Horwich, Atherton, Leigh, and Standish. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"tjxkm27588","nodes":[{"id":"hlyk727589","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"1laqn12825","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Bolton and Wigan"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"r0k1k27591","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"oqxdb12827","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and music classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"35u7a27593","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"heps312829","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"ic55h27595","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"u45vq12831","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"4lzfu27597","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"kvbiq12833","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Bolton and Wigan''s communities are fiercely loyal and deeply connected. These are towns where people look after their own, and a Memory Catcher who becomes part of that community will find the support and trust that makes the franchise model work.', null, 'Baby Keepsake Franchise Opportunity in Bolton and Wigan', 'Start a flexible Memory Catcher franchise across Bolton and Wigan. Capture baby handprints and footprints locally with full training, support, and a protected region.', 53.57, -2.53, 470000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('swindon-wiltshire', 'Swindon', 'Swindon and North Wiltshire', true, '£3,445', 'Full-Time', 'A flexible, family-friendly franchise capturing baby handprints and footprints across Swindon and Wiltshire''s growing family communities.', 'Swindon, Chippenham, Trowbridge, Devizes, Calne, Marlborough', 'Fast-growing Swindon, Marlborough ultra-premium, M4 corridor connectivity, 400K+ territory.', 'NCT Swindon and Wiltshire, multiple independent baby class providers, family centres', '{"documentStyle":{},"nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"om3sk12602","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Swindon is one of the fastest-growing towns in the South West with a population exceeding 230,000. The M4 corridor brings London commuters. Marlborough adds ultra-premium heritage charm. The territory exceeds 400,000."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"e8xs712604","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"cgqpw12605","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Swindon''s growing suburbs attract young families. Marlborough is one of Wiltshire''s most affluent towns. Chippenham and Trowbridge provide established community depth."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"fyy9612607","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"qzx8p12608","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT runs groups across the area. Independent baby classes operate throughout. The growing population means an expanding baby class scene."},"type":"TEXT"}],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"xy4nt12610","nodes":[],"type":"PARAGRAPH"},{"paragraphData":{"textStyle":{"lineHeight":"1.3","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"y7hxc12611","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Swindon''s growth trajectory and Marlborough''s premium market create a territory that''s both expanding and quality-driven."},"type":"TEXT"}],"type":"PARAGRAPH"}]}', 'Your Swindon and North Wiltshire region covers Swindon, Chippenham, Trowbridge, Devizes, Calne, and Marlborough. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle":{},"nodes":[{"bulletedListData":{"indentation":0},"id":"vlit537115","nodes":[{"id":"4ikhg37116","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"9mex420510","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"NCT Swindon and Wiltshire"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"hj1ta37118","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"7xbwo20512","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Independent baby sensory and development classes"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"pznvl37120","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"liw4u20514","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Community centres and church halls"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"v9lv037122","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"v88ot20516","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Family hubs and children''s centres"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"},{"id":"56fwz37124","nodes":[{"paragraphData":{"textStyle":{"lineHeight":"1.8","textAlignment":"AUTO"}},"style":{"paddingBottom":"0px","paddingTop":"0px"},"id":"5l88y20518","nodes":[{"id":"","nodes":[],"textData":{"decorations":[],"text":"Library baby groups"},"type":"TEXT"}],"type":"PARAGRAPH"}],"type":"LIST_ITEM"}],"type":"BULLETED_LIST"}]}', 'Swindon and Wiltshire''s family communities are growing and welcoming.', null, 'Baby Keepsake Franchise Opportunity in Swindon', 'Start a flexible Memory Catcher franchise across Swindon and North Wiltshire. Capture baby handprints and footprints locally with full training and support.', 51.55, -1.85, 400000)
insert into public.franchise_regions (slug, city_name, region, is_available, buy_in, franchise_potential, hero_subtitle, coverage_areas, card_profile_summary, baby_classes_in_area, why_area, region_coverage_desc, baby_classes_list, community_note, franchisee_bio, meta_title, meta_description, latitude, longitude, population) values ('isle-of-man', 'Isle of Man', 'Isle of Man', true, '£3,445', 'Either', 'A flexible, family-friendly franchise capturing baby handprints and footprints across the Isle of Man''s close-knit island community.', 'Douglas, Onchan, Ramsey, Peel, Castletown, Port Erin', '84K+ self-governing island, zero competition, whole-island territory, strong national identity, boutique market.', 'Independent baby class providers, family centres, community groups', '{"documentStyle": {}, "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "pjxbg23358", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "The Isle of Man has a population of around 84,000 and is a self-governing Crown Dependency with its own parliament, health service and strong national identity. It is not part of the United Kingdom, and islanders are proud of that distinction."}, "type": "TEXT"}], "type": "PARAGRAPH"}, {"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "vjgge84396", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Island communities are exceptionally close-knit. When a family loves a product or service, word travels across the whole island quickly. That organic word of mouth is unmatched anywhere on the mainland."}, "type": "TEXT"}], "type": "PARAGRAPH"}, {"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "ypdce62080", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "The island has no Memory Catcher and no direct competitor offering foil keepsakes. A single Memory Catcher covers the entire island, which makes the territory genuinely self-contained."}, "type": "TEXT"}], "type": "PARAGRAPH"}, {"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "4azg472753", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Douglas is the capital and commercial centre, with Onchan, Ramsey, Peel, Castletown and the southern villages all within a short drive. Nowhere on the island is more than an hour from anywhere else."}, "type": "TEXT"}], "type": "PARAGRAPH"}, {"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "lks3r33583", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Independent baby classes and family groups run from community centres, family hubs and church halls across the main towns."}, "type": "TEXT"}], "type": "PARAGRAPH"}, {"paragraphData": {"textStyle": {"lineHeight": "1.3", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "tlakd34216", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "The Isle of Man is a boutique territory: smaller in population but completely self-contained with zero competition. It works well as a part-time business, or full-time alongside strong local networking."}, "type": "TEXT"}], "type": "PARAGRAPH"}]}', 'Your Isle of Man region covers Douglas, Onchan, Ramsey, Peel, Castletown, and Port Erin - the whole island. This is your exclusive area, and no other Memory Catcher will operate here.', '{"documentStyle": {}, "nodes": [{"bulletedListData": {"indentation": 0}, "id": "da61h48038", "nodes": [{"id": "5nhgs17106", "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.8", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "x2wlg81303", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Independent baby classes"}, "type": "TEXT"}], "type": "PARAGRAPH"}], "type": "LIST_ITEM"}, {"id": "pe6tc28597", "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.8", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "6kumr63708", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Community centres and church halls"}, "type": "TEXT"}], "type": "PARAGRAPH"}], "type": "LIST_ITEM"}, {"id": "uu16g60002", "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.8", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "i9i5766754", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Family hubs and children''s centres"}, "type": "TEXT"}], "type": "PARAGRAPH"}], "type": "LIST_ITEM"}, {"id": "c1wmv69904", "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.8", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "q3y5k40851", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Library baby groups"}, "type": "TEXT"}], "type": "PARAGRAPH"}], "type": "LIST_ITEM"}, {"id": "lxsm949206", "nodes": [{"paragraphData": {"textStyle": {"lineHeight": "1.8", "textAlignment": "AUTO"}}, "style": {"paddingBottom": "0px", "paddingTop": "0px"}, "id": "amj9435367", "nodes": [{"id": "", "nodes": [], "textData": {"decorations": [], "text": "Island parent and baby networks"}, "type": "TEXT"}], "type": "PARAGRAPH"}], "type": "LIST_ITEM"}], "type": "BULLETED_LIST"}]}', 'Island communities are close-knit, loyal, and proud of their Manx identity.', null, 'Baby Keepsake Franchise Opportunity on the Isle of Man', 'Start a flexible Memory Catcher franchise on the Isle of Man. Capture baby handprints and footprints across this unique island community with full training and support.', 54.15, -4.48, 84000)
